-- Name: shifts_reassign(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.shifts_reassign(p_ws uuid, p_shift uuid, p_staff uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'public'
