-- ---- from 20261112003400_chat-message-status-created-index.sql ----
-- chat-message-status-created-index: forward-only; immutable once on origin/main.
-- A node read of a conversation's posted lines (chatbot.thread) pins conversationId and status and reads newest first by createdAt,
-- which no declared index served: QUERY_NOT_INDEXED parked every front-desk run.

-- create_index public.records_chat_message:index:records_chat_message_conversation_status_created: on workspace_id, data->>'conversationid', data->>'status', created_atdesc, iddesc using btree
CREATE INDEX "records_chat_message_conversation_status_created" ON public."records_chat_message" USING btree (workspace_id, ((data->>'conversationId')::uuid), (data->>'status'), created_at DESC, id DESC);

-- ---- from 20261112004700_chat-conversation-lead-field.sql ----
-- chat-conversation-lead-field: forward-only; immutable once on origin/main.
-- A conversation was tied to its customer by the `lead` link (record_links) only; its `leadId` field stayed empty. The graph nodes find a
-- customer's conversation by that field (the payment confirmation, the Sales after-sale thanks), so after a payment the customer was told
-- nothing. The code now writes both; this fills the field from the link for the conversations tied before. Data only, idempotent.

UPDATE public.records AS c
SET data = jsonb_set(c.data, '{leadId}', to_jsonb(l.to_id::text)),
    version = c.version + 1,
    updated_at = now()
FROM public.record_links AS l
WHERE c.entity = 'chat.conversation'
  AND l.from_entity = 'chat.conversation'
  AND l.from_id = c.id
  AND l.workspace_id = c.workspace_id
  AND l.relation = 'lead'
  AND l.to_entity = 'sales.lead'
  AND (c.data->>'leadId') IS NULL;

