-- The JSON rewriter: every string VALUE and every object KEY equal to an old id is replaced; nothing else is touched (a longer string
-- holding an id, a ref such as lead.address, a node id such as payment.settle stay). plpgsql: a recursive LANGUAGE sql function fails
-- body validation at CREATE.
CREATE FUNCTION pg_temp.flip_json(p jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $f$
BEGIN
  IF p IS NULL THEN RETURN NULL; END IF;
  CASE jsonb_typeof(p)
    WHEN 'string' THEN
      RETURN COALESCE((SELECT to_jsonb(m.new) FROM flip_map m WHERE m.old = p #>> '{}'), p);
    WHEN 'array' THEN
      RETURN COALESCE((SELECT jsonb_agg(pg_temp.flip_json(e) ORDER BY i) FROM jsonb_array_elements(p) WITH ORDINALITY AS a(e, i)), '[]'::jsonb);
    WHEN 'object' THEN
      RETURN COALESCE((SELECT jsonb_object_agg(COALESCE((SELECT m.new FROM flip_map m WHERE m.old = o.k), o.k), pg_temp.flip_json(o.v))
                         FROM jsonb_each(p) AS o(k, v)), '{}'::jsonb);
    ELSE
      RETURN p;
  END CASE;
END
$f$;

-- Whether a JSON document still holds an old id as a whole string value or key (its exact quoted form in the text).
CREATE FUNCTION pg_temp.flip_has_old(p jsonb) RETURNS boolean
    LANGUAGE sql STABLE
    AS $f$
  SELECT EXISTS (SELECT 1 FROM flip_map m WHERE position(to_jsonb(m.old)::text IN p::text) > 0)
$f$;

-- ---------------------------------------------------------------------------------------------------------------------------------
-- 2. public.mcp_tool_grants.tool (unique (agent_id, tool); CHECK mcp_tool_grants_tool_check of the baseline:
--    ^[a-z][a-z0-9-]{1,30}\.([a-zA-Z][a-zA-Z0-9_.]{1,80}|\*)$ — it holds every new exact id but nivo.team-chat.* and a namespaced
--    wildcard, which the contract half renames after widening it).
--
-- 2a. customer.* and lead.* expand into their exact tools (nivo.lead.* would also grant the context reads and the customer send).
INSERT INTO public.mcp_tool_grants (workspace_id, agent_id, tool, mode, limit_vnd, constraints, updated_by)
SELECT g.workspace_id, g.agent_id, x.tool, g.mode, g.limit_vnd, g.constraints, g.updated_by
  FROM public.mcp_tool_grants g
  JOIN (VALUES ('customer.*', 'nivo.lead.message.send'), ('customer.*', 'nivo.lead.care.schedule'),
               ('lead.*', 'nivo.lead.ensure'), ('lead.*', 'nivo.lead.update'), ('lead.*', 'nivo.lead.stage.update')) AS x(wild, tool)
    ON x.wild = g.tool
ON CONFLICT (agent_id, tool) DO NOTHING;
DELETE FROM public.mcp_tool_grants WHERE tool IN ('customer.*', 'lead.*');

-- 2b. customer.care.send (folded before the flip; last resort): carried to the one send unless the agent already holds it.
UPDATE public.mcp_tool_grants g SET tool = 'nivo.lead.message.send', updated_at = now()
 WHERE g.tool = 'customer.care.send'
   AND NOT EXISTS (SELECT 1 FROM public.mcp_tool_grants o
                    WHERE o.agent_id = g.agent_id AND o.tool IN ('nivo.lead.message.send', 'customer.message.send'));
DELETE FROM public.mcp_tool_grants g USING flip_absent a WHERE g.tool = a.old;

-- 2c. An agent holding both names (a row written under the new name before the flip): the new row wins.
DELETE FROM public.mcp_tool_grants g
 USING flip_map m
 WHERE g.tool = m.old
   AND m.new NOT LIKE 'nivo.team-chat.%'
   AND EXISTS (SELECT 1 FROM public.mcp_tool_grants o WHERE o.agent_id = g.agent_id AND o.tool = m.new);

-- 2d. Rename every exact grant the current CHECK can hold (all but nivo.team-chat.*: the contract half).
UPDATE public.mcp_tool_grants g SET tool = m.new, updated_at = now()
  FROM flip_map m
 WHERE g.tool = m.old AND m.new NOT LIKE 'nivo.team-chat.%';

-- ---------------------------------------------------------------------------------------------------------------------------------
-- 3. public.workspaces_nivo_agent() (trigger on public.workspaces; live body = 20261112012300): a new workspace's internal agent gets
--    its door grants from this list. Same four tools, new names (team-chat report/approval are held by DOOR_GRANTS in code, as before).
CREATE OR REPLACE FUNCTION public.workspaces_nivo_agent() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_agent uuid;
begin
  insert into public.agents (workspace_id, module, name, handle, role, instructions, status)
  values (new.id, 'nivo', 'Nivo', 'nivo', 'Runs the declared jobs of the modules',
          'Internal. Calls only the door tools the declared jobs of the modules name.', 'paused')
  returning id into v_agent;
  insert into public.mcp_tool_grants (workspace_id, agent_id, tool, mode)
  select new.id, v_agent, tool, 'auto'
  from unnest(array['nivo.chat.send', 'nivo.chat.profile.get', 'nivo.ledger.entry.append', 'nivo.ledger.status.get']) as tool;
  return null;
end;
$$;

-- ---------------------------------------------------------------------------------------------------------------------------------
-- 4. Workflow documents (entity-engine records; parent public.records(entity, id, workspace_id, data jsonb, version, created_at,
--    updated_at), one partition per entity). Steps hold tool ids under `tools`, `effects`, `requires`; grants under the workflow's
--    rights. A rewritten version keeps its old `documentHash`: on dev the workflows are re-adopted from the templates after the restart
--    (`reset-workflows`), and production re-adopts at its deploy; the rewrite keeps every stored version consistent meanwhile.
UPDATE public.records SET data = pg_temp.flip_json(data), version = version + 1, updated_at = now()
 WHERE entity IN ('agent.graph', 'agent.graph-version', 'agent.workflow', 'agent.workflow-version', 'agent.graph-proposal')
   AND pg_temp.flip_has_old(data);

-- ---------------------------------------------------------------------------------------------------------------------------------
-- 5. Context snapshots of installations (public.module_context_versions(snapshot jsonb); the table has no updated_at).
UPDATE public.module_context_versions SET snapshot = pg_temp.flip_json(snapshot) WHERE pg_temp.flip_has_old(snapshot);

-- ---------------------------------------------------------------------------------------------------------------------------------
-- 6. The native connector row of the effect domain `customer` (status / time limit of a workspace): its tools now live under the
--    domain `lead` (nivo.lead.message.send, nivo.lead.care.schedule). A workspace that already has a `lead` row keeps that one.
DELETE FROM public.mcp_connectors c
 WHERE c.kind = 'native' AND c.key = 'customer'
   AND EXISTS (SELECT 1 FROM public.mcp_connectors o WHERE o.workspace_id = c.workspace_id AND o.key = 'lead');
UPDATE public.mcp_connectors SET key = 'lead', name = 'NIVO lead', updated_at = now() WHERE kind = 'native' AND key = 'customer';

-- ---------------------------------------------------------------------------------------------------------------------------------
-- 7. Free text that may NAME a tool (shop-written; never rewritten by a machine): counted, reported as a NOTICE, fixed by hand.
DO $$
DECLARE
  v_re text;
  v_agents bigint; v_facts bigint; v_templates bigint;
BEGIN
  SELECT '(^|[^A-Za-z0-9_./@$-])(' || string_agg(regexp_replace(old, '([.*])', '\\\1', 'g'), '|' ORDER BY length(old) DESC) || ')($|[^A-Za-z0-9_*-])'
    INTO v_re FROM flip_map;
  SELECT count(*) INTO v_agents FROM public.agents
   WHERE instructions ~ v_re OR knowledge ~ v_re OR approval_rule ~ v_re OR greeting ~ v_re;
  SELECT count(*) INTO v_facts FROM public.brain_facts WHERE value ~ v_re OR coalesce(decision_note, '') ~ v_re;
  SELECT count(*) INTO v_templates FROM public.agent_template_versions WHERE package::text ~ v_re;
  RAISE NOTICE 'tool-names-nivo: text naming an old tool id (by hand, not by this migration): agents=% brain_facts=% template_versions(history)=%',
    v_agents, v_facts, v_templates;
END
$$;

-- ---------------------------------------------------------------------------------------------------------------------------------
-- 8. Final check: the file fails (and rolls back) when an old id is left in a LIVE store this half owns.
DO $$
DECLARE
  v_grants bigint; v_docs bigint; v_snap bigint; v_fn bigint; v_rows bigint;
BEGIN
  SELECT count(*) INTO v_grants FROM public.mcp_tool_grants g
   WHERE (g.tool IN (SELECT old FROM flip_map WHERE new NOT LIKE 'nivo.team-chat.%') OR g.tool IN (SELECT old FROM flip_absent)
          OR g.tool IN ('customer.*', 'lead.*'));
  SELECT count(*) INTO v_docs FROM public.records
   WHERE entity IN ('agent.graph', 'agent.graph-version', 'agent.workflow', 'agent.workflow-version', 'agent.graph-proposal')
     AND pg_temp.flip_has_old(data);
  SELECT count(*) INTO v_snap FROM public.module_context_versions WHERE pg_temp.flip_has_old(snapshot);
  -- a live SQL function body that still names an old tool id as a quoted literal
  SELECT count(*) INTO v_fn FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
   WHERE n.nspname = 'public'
     AND EXISTS (SELECT 1 FROM flip_map m WHERE position(quote_literal(m.old) IN p.prosrc) > 0);
  SELECT count(*) INTO v_rows FROM public.mcp_connectors WHERE kind = 'native' AND key = 'customer';
  IF v_grants + v_docs + v_snap + v_fn + v_rows > 0 THEN
    RAISE EXCEPTION 'tool-names-nivo: old ids remain: grants=% workflow_docs=% context_snapshots=% sql_functions=% customer_rows=%',
      v_grants, v_docs, v_snap, v_fn, v_rows;
  END IF;
END
$$;

-- ---- from 20261112014201_tool-names_contract_grant-check.sql ----
-- tool-names_contract_grant-check: forward-only; immutable once on origin/main. CONTRACT half of the tool-name flip; runs after
-- 20261112014200_tool-names-nivo.sql (expand), once the release is accepted.
--
-- public.mcp_tool_grants_tool_check (baseline) refuses a hyphen after the first dot and any namespaced wildcard, so it cannot hold
-- `nivo.team-chat.report.post`, `nivo.team-chat.approval.post` or `nivo.ledger.*`. It is replaced by the CHECK of the flipped names:
--   * an exact grant: `<prefix>.<tool>` where the prefix is a connector key and the tool may hold dots and hyphens
--     (`nivo.team-chat.report.post`, `google.drive.status.get`, a remote `shop.order.place`);
--   * a wildcard: a prefix of one or more segments and `.*` (`sepay.*`, `nivo.ledger.*`, `google.drive.*`);
--   * NEVER a bare `nivo.*` (it would grant every native tool NIVO has; the gateway covers nothing with it either).
-- Then the two kinds of stored grant the expand half could not rename under the old CHECK are renamed: the team-chat door tools and
-- the wildcards (`ledger.*` -> `nivo.ledger.*` covers the same tools it covered before; `drive.*` -> `google.drive.*`; `agent.*` was
-- deleted by the expand half). Until this file runs, such a stored grant names nothing the gateway knows (default deny): dev has none.
-- No drain is needed here: nothing open keys a ledger entry by a grant row.
ALTER TABLE public.mcp_tool_grants DROP CONSTRAINT mcp_tool_grants_tool_check;
ALTER TABLE public.mcp_tool_grants ADD CONSTRAINT mcp_tool_grants_tool_check CHECK (
  tool ~ '^[a-z][a-z0-9-]{1,30}\.(([a-z][a-z0-9-]*\.)*[a-zA-Z][a-zA-Z0-9_-]*|([a-z][a-z0-9-]*\.)*\*)$'
  AND char_length(tool) <= 120
  AND tool <> 'nivo.*'
) NOT VALID;

CREATE TEMP TABLE flip_rest (old text PRIMARY KEY, new text NOT NULL) ON COMMIT DROP;
INSERT INTO flip_rest (old, new) VALUES
  ('team-chat.post-report',   'nivo.team-chat.report.post'),
  ('team-chat.post-approval', 'nivo.team-chat.approval.post'),
  ('ledger.*',    'nivo.ledger.*'),
  ('bank.*',      'nivo.bank.*'),
  ('brain.*',     'nivo.brain.*'),
  ('drive.*',     'google.drive.*'),
  ('dossier.*',   'nivo.dossier.*'),
  ('einvoice.*',  'nivo.einvoice.*'),
  ('chat.*',      'nivo.chat.*'),
  ('team-chat.*', 'nivo.team-chat.*'),
  ('order.*',     'nivo.order.*'),
  ('payment.*',   'nivo.payment.*'),
  ('team.*',      'nivo.team.*'),
  ('work.*',      'nivo.work.*'),
  ('report.*',    'nivo.report.*');

-- An agent holding both names: the new row wins.
DELETE FROM public.mcp_tool_grants g
 USING flip_rest m
 WHERE g.tool = m.old
   AND EXISTS (SELECT 1 FROM public.mcp_tool_grants o WHERE o.agent_id = g.agent_id AND o.tool = m.new);
UPDATE public.mcp_tool_grants g SET tool = m.new, updated_at = now() FROM flip_rest m WHERE g.tool = m.old;
-- A bare nivo.* written by hand before this file (the old CHECK allowed it) grants nothing: removed so the new CHECK validates.
DELETE FROM public.mcp_tool_grants WHERE tool = 'nivo.*';

ALTER TABLE public.mcp_tool_grants VALIDATE CONSTRAINT mcp_tool_grants_tool_check;

-- Final check: no grant left on an OLD native connector or effect domain (a tool born old-style after the flip table, or a row the
-- expand half did not know).
DO $$
DECLARE
  v_left bigint;
BEGIN
  SELECT count(*) INTO v_left FROM public.mcp_tool_grants
   WHERE tool ~ '^(customer|lead|order|payment|team|agent|work|report|ledger|bank|brain|drive|dossier|einvoice|chat|team-chat|ai)\.';
  IF v_left > 0 THEN
    RAISE EXCEPTION 'tool-names_contract_grant-check: % grants still name an old native connector or effect domain', v_left;
  END IF;
END
$$;

-- ---- from 20261112014400_abilities-from-task-rules.sql ----
-- abilities-from-task-rules: forward-only; immutable once on origin/main. EXPAND (nothing is dropped here).
-- The old task rules (public.authority_rules: mode, VND limit, approvers, required fields) are no longer read by the work engine
-- (owner 2026-11-11: "bản thân nó có policy trên từng providers rồi! xóa!"). A module action that acts through a connected account is
-- now decided by the acting agent's ability on that account (public.mcp_connector_access.abilities: {"<ability>": "auto" | "ask"};
-- a key that is absent is off). This carries each workspace's rule MODE onto those abilities, so what a shop chose keeps holding:
--
--   rule actions (department = the agent's module)                     ability           providers
--   reply_customer, send_follow_up, send_quote, send_care, issue_invoice,  customer.send     zalo_oa, telegram, meta
--   greet_prospect, ask_qualifying, follow_up_lead, close_lead,
--   reply_comment_public, private_reply_comment, message_with_human_agent_tag
--   send_email                                                          email.send        smtp
--
-- Several rules of one agent on one ability: any 'never' carries nothing (the key stays absent = off), else any 'ask' gives 'ask',
-- else 'auto'. A rule that names agents applies to those agents only; one that names none applies to every active agent of its module.
-- An ability the shop already set (the key exists) is NEVER overwritten. The VND limits, approvers and required fields are not
-- carried (owner's decision: no ceilings, the owner approves, default = report).
--
-- smtp is a provider of the rights catalogue only from this change on, so no agent is attached to an SMTP account yet. Block 3
-- attaches the agents a 'send_email' rule covered to the workspace's working SMTP accounts with the rule's mode, so customer email
-- keeps working the day the rules stop being read (otherwise every customer email is refused until the owner attaches by hand).
-- Insert-missing only (the agent's attachment to that account, if any, is left as it is).

-- 1. customer.send on the messaging accounts the agents are attached to.
WITH carried AS (
    SELECT r.workspace_id,
           a.id AS agent_id,
           CASE
               WHEN bool_or(r.mode = 'never') THEN NULL
               WHEN bool_or(r.mode = 'ask') THEN 'ask'
               ELSE 'auto'
           END AS mode
      FROM public.authority_rules r
      JOIN public.agents a
        ON a.workspace_id = r.workspace_id
       AND a.module = r.department
       AND a.status = 'active'
     WHERE r.action = ANY (ARRAY[
               'reply_customer', 'send_follow_up', 'send_quote', 'send_care', 'issue_invoice', 'greet_prospect',
               'ask_qualifying', 'follow_up_lead', 'close_lead', 'reply_comment_public', 'private_reply_comment',
               'message_with_human_agent_tag'
           ]::text[])
       AND (cardinality(r.agents) = 0 OR a.id = ANY (r.agents))
     GROUP BY r.workspace_id, a.id
)
UPDATE public.mcp_connector_access x
   SET abilities = x.abilities || jsonb_build_object('customer.send', c.mode)
  FROM carried c
 WHERE x.workspace_id = c.workspace_id
   AND x.agent_id = c.agent_id
   AND x.provider = ANY (ARRAY['zalo_oa', 'telegram', 'meta']::text[])
   AND c.mode IS NOT NULL
   AND (x.abilities -> 'customer.send') IS NULL;

-- 2. email.send on SMTP accounts an agent is already attached to (none before this change; kept so a re-run stays correct).
WITH carried AS (
    SELECT r.workspace_id,
           a.id AS agent_id,
           CASE
               WHEN bool_or(r.mode = 'never') THEN NULL
               WHEN bool_or(r.mode = 'ask') THEN 'ask'
               ELSE 'auto'
           END AS mode
      FROM public.authority_rules r
      JOIN public.agents a
        ON a.workspace_id = r.workspace_id
       AND a.module = r.department
       AND a.status = 'active'
     WHERE r.action = 'send_email'
       AND (cardinality(r.agents) = 0 OR a.id = ANY (r.agents))
     GROUP BY r.workspace_id, a.id
)
UPDATE public.mcp_connector_access x
   SET abilities = x.abilities || jsonb_build_object('email.send', c.mode)
  FROM carried c
 WHERE x.workspace_id = c.workspace_id
   AND x.agent_id = c.agent_id
   AND x.provider = 'smtp'
   AND c.mode IS NOT NULL
   AND (x.abilities -> 'email.send') IS NULL;

-- 3. Attach the agents a send_email rule covered ('auto' or 'ask') to every working SMTP account of their workspace.
INSERT INTO public.mcp_connector_access (workspace_id, agent_id, provider, abilities, connection_id)
SELECT c.workspace_id, c.agent_id, 'smtp', jsonb_build_object('email.send', c.mode), s.id
  FROM (
        SELECT r.workspace_id,
               a.id AS agent_id,
               CASE
                   WHEN bool_or(r.mode = 'never') THEN NULL
                   WHEN bool_or(r.mode = 'ask') THEN 'ask'
                   ELSE 'auto'
               END AS mode
          FROM public.authority_rules r
          JOIN public.agents a
            ON a.workspace_id = r.workspace_id
           AND a.module = r.department
           AND a.status = 'active'
         WHERE r.action = 'send_email'
           AND (cardinality(r.agents) = 0 OR a.id = ANY (r.agents))
         GROUP BY r.workspace_id, a.id
       ) c
  JOIN public.connections s
    ON s.workspace_id = c.workspace_id
   AND s.provider = 'smtp'
   AND s.status = 'connected'
 WHERE c.mode IS NOT NULL
ON CONFLICT ON CONSTRAINT mcp_connector_access_agent_connection_unique DO NOTHING;

-- ---- from 20261112014500_brain-policies.sql ----
-- brain-policies: forward-only; immutable once on origin/main. Expand only: two new tables, nothing else touched.
-- The "Chính sách" tab of the Second Brain is an AI-DERIVED LAYER over the truth graph (owner, 2026-11-11: "mỗi lần truth graph được
-- tạo ra có một AI suy ra chính sách; nếu graph thay đổi thì AI đối chiếu thay đổi để thêm / sửa chính sách; có thể sửa bằng tham số,
-- và khi sửa tham số thì thay đổi truth graph"). A row of brain_policies is the AI's judgement of ONE truth (subject + attribute +
-- instance scope): whether it is a rule of how the shop operates (kind policy) or not (kind not_policy: identity data such as the
-- address or the phone, catalogue data), with a human title, a group, the value type and a short reason. It is bound to the fact it
-- was derived from (fact_id + fact_version) and holds NO value: the tab always reads the value from the fact in force. A new version of
-- the same truth re-binds without a model call while `basis` (a hash of what the judgement read: subject type, labels, value type)
-- is unchanged; a changed basis is compared by the model again. A truth with nothing in force or scheduled is retired, never deleted.
-- brain_policy_derivations is the state of the derive pass per workspace (queued / running / idle / failed), what the tab shows as
-- "đang suy ra" and where a failure is recorded. Soft policy only: agents read facts, never these tables.

CREATE TABLE public.brain_policies (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,
    subject_key text NOT NULL,
    attribute text NOT NULL,
    installation_id uuid,
    fact_id uuid NOT NULL,
    fact_version integer,
    basis text NOT NULL,
    kind text NOT NULL,
    title text DEFAULT ''::text NOT NULL,
    group_key text DEFAULT ''::text NOT NULL,
    group_label text DEFAULT ''::text NOT NULL,
    value_type text NOT NULL,
    reason text DEFAULT ''::text NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    model text,
    derived_at timestamptz DEFAULT now() NOT NULL,
    retired_at timestamptz,
    created_at timestamptz DEFAULT now() NOT NULL,
    updated_at timestamptz DEFAULT now() NOT NULL,
    CONSTRAINT brain_policies_kind_check CHECK ((kind = ANY (ARRAY['policy'::text, 'not_policy'::text]))),
    CONSTRAINT brain_policies_status_check CHECK ((status = ANY (ARRAY['open'::text, 'retired'::text]))),
    CONSTRAINT brain_policies_value_type_check CHECK ((value_type = ANY (ARRAY['money'::text, 'percent'::text, 'duration'::text, 'time_range'::text, 'boolean'::text, 'text'::text]))),
    CONSTRAINT brain_policies_title_check CHECK ((char_length(title) <= 120)),
    CONSTRAINT brain_policies_group_check CHECK ((char_length(group_label) <= 80)),
    CONSTRAINT brain_policies_reason_check CHECK ((char_length(reason) <= 300))
);

-- One judgement per truth: the derive pass is safe to run twice (a second insert of the same truth is ignored).
CREATE UNIQUE INDEX brain_policies_truth ON public.brain_policies USING btree (workspace_id, subject_key, attribute, COALESCE(installation_id, '00000000-0000-0000-0000-000000000000'::uuid));
-- The tab and the derive pass read every judgement of a workspace by status.
CREATE INDEX brain_policies_ws_status ON public.brain_policies USING btree (workspace_id, status);

CREATE TRIGGER brain_policies_set_updated_at BEFORE UPDATE ON public.brain_policies FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

ALTER TABLE public.brain_policies ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.brain_policies FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.brain_policies TO app_be;
CREATE POLICY brain_policies_app_be_select ON public.brain_policies FOR SELECT TO app_be USING ((workspace_id IS NOT NULL));
CREATE POLICY brain_policies_app_be_insert ON public.brain_policies FOR INSERT TO app_be WITH CHECK ((workspace_id IS NOT NULL));
CREATE POLICY brain_policies_app_be_update ON public.brain_policies FOR UPDATE TO app_be USING ((workspace_id IS NOT NULL)) WITH CHECK ((workspace_id IS NOT NULL));
CREATE POLICY brain_policies_app_be_delete ON public.brain_policies FOR DELETE TO app_be USING ((workspace_id IS NOT NULL));

CREATE TABLE public.brain_policy_derivations (
    workspace_id uuid NOT NULL PRIMARY KEY REFERENCES public.workspaces(id) ON DELETE CASCADE,
    status text DEFAULT 'queued'::text NOT NULL,
    requested_at timestamptz DEFAULT now() NOT NULL,
    started_at timestamptz,
    derived_at timestamptz,
    attempts integer DEFAULT 0 NOT NULL,
    error text,
    created_at timestamptz DEFAULT now() NOT NULL,
    updated_at timestamptz DEFAULT now() NOT NULL,
    CONSTRAINT brain_policy_derivations_status_check CHECK ((status = ANY (ARRAY['queued'::text, 'running'::text, 'idle'::text, 'failed'::text]))),
    CONSTRAINT brain_policy_derivations_error_check CHECK (((error IS NULL) OR (error = ANY (ARRAY['model'::text, 'credits'::text, 'gave_up'::text]))))
);

CREATE TRIGGER brain_policy_derivations_set_updated_at BEFORE UPDATE ON public.brain_policy_derivations FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

ALTER TABLE public.brain_policy_derivations ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.brain_policy_derivations FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.brain_policy_derivations TO app_be;
CREATE POLICY brain_policy_derivations_app_be_select ON public.brain_policy_derivations FOR SELECT TO app_be USING ((workspace_id IS NOT NULL));
CREATE POLICY brain_policy_derivations_app_be_insert ON public.brain_policy_derivations FOR INSERT TO app_be WITH CHECK ((workspace_id IS NOT NULL));
CREATE POLICY brain_policy_derivations_app_be_update ON public.brain_policy_derivations FOR UPDATE TO app_be USING ((workspace_id IS NOT NULL)) WITH CHECK ((workspace_id IS NOT NULL));
CREATE POLICY brain_policy_derivations_app_be_delete ON public.brain_policy_derivations FOR DELETE TO app_be USING ((workspace_id IS NOT NULL));

-- ---- from 20261112014800_brain-facts-upkeep.sql ----
-- brain-facts-upkeep: forward-only; immutable once on origin/main. Expand only: two partial indexes on public.brain_facts, nothing else.
-- The timed brain upkeep (tick `brain-upkeep`, every 5 minutes, BR1) asks across workspaces which ones have upkeep due
-- (`BrainFactsReadService.dueWorkspaces`):
--   SELECT DISTINCT workspace_id FROM brain_facts
--   WHERE (status = 'scheduled' AND valid_from <= now()) OR (status = 'active' AND valid_to < now()) LIMIT 200
-- No index covered it, so every tick scanned the whole table. Each branch of the OR now has its own partial index whose predicate is the
-- branch's status, so the planner reads both by range (BitmapOr) and touches only the few rows in that state; both stay small (a fact
-- is scheduled only until its start, and active is one row per truth).

CREATE INDEX brain_facts_scheduled_start ON public.brain_facts USING btree (valid_from) WHERE (status = 'scheduled'::text);
CREATE INDEX brain_facts_active_end ON public.brain_facts USING btree (valid_to) WHERE (status = 'active'::text);

-- ---- from 20261112014900_agent-work-lease-expire.sql ----
-- agent-work-lease-expire: forward-only; immutable once on origin/main. Expand only: one new function, no table altered, no grant widened.
--
-- The lease rows are written by the database functions only (agent-work-core: "the back end calls them and never touches the lease
-- rows"), so app_be holds SELECT on agent_work_leases and nothing more. The retention of the minute sweep removed the lease row of an
-- idle customer conversation with a plain DELETE as app_be, which the database refuses ("permission denied for table agent_work_leases").
-- It only showed once a conversation had been idle for two days: from then on every minute's sweep job failed at its last step, four
-- tries each. The removal now goes through this function, under the same rule as the rest of the lease story: a row is removed only
-- while no turn runs in it, it is a customer conversation's, it has been idle since `p_before`, and its scope has no pending or running
-- wake (the fence restarts at zero with a new row, so a scope that still has work keeps its row). A row another worker holds is skipped,
-- never waited on. Answers how many rows went.

CREATE OR REPLACE FUNCTION public.agent_work_leases_expire(p_before timestamptz, p_limit integer) RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_removed integer;
BEGIN
  WITH idle AS (
    SELECT l.agent_id, l.scope_key FROM public.agent_work_leases l
     WHERE l.scope_key LIKE 'conversation:%'
       AND l.running_turn_id IS NULL
       AND l.updated_at < p_before
       AND NOT EXISTS (
         SELECT 1 FROM public.agent_wakes w
          WHERE w.agent_id = l.agent_id AND w.scope_key = l.scope_key AND w.status IN ('pending', 'running')
       )
     ORDER BY l.updated_at
     LIMIT greatest(coalesce(p_limit, 0), 0)
     FOR UPDATE SKIP LOCKED
  ), removed AS (
    DELETE FROM public.agent_work_leases l USING idle
     WHERE l.agent_id = idle.agent_id AND l.scope_key = idle.scope_key AND l.running_turn_id IS NULL
    RETURNING 1
  )
  SELECT count(*)::integer INTO v_removed FROM removed;
  RETURN v_removed;
END;
$$;
REVOKE ALL ON FUNCTION public.agent_work_leases_expire(timestamptz, integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.agent_work_leases_expire(timestamptz, integer) TO app_be;

-- ---- from 20261112015000_chat-nivo-line-card.sql ----
-- chat-nivo-line-card: forward-only; immutable once on origin/main. Expand only: one check re-created wider, one partial unique index.
-- NIVO itself (no agent, no run) tells the founder that a background job stopped (the policy derive pass first): ONE typed card per
-- failure episode, posted as a system line (author_kind 'system', author_id NULL) in the founder's NIVO room (a direct room keyed
-- 'system:nivo|user:<owner>'). Two things stood in the way:
-- 1. chat_room_messages_ref_check let only an agent's text line (or a person's forward) carry the structured message in
--    ref.agent_message; a system line had to have no ref. Every clause of the check is kept exactly as 20261112002800 wrote it; one
--    clause is added: a system line may carry ref.agent_message (JSON text), the same shape an agent's card line has. The new clause
--    tests `ref ? 'agent_message'` first: without it a missing key makes the clause NULL, which a CHECK lets through.
-- 2. chat_room_messages_client_key is (room_id, author_id, client_id): author_id is NULL on every system line and NULLs are distinct, so
--    a retry key never matched a system line. chat_room_messages_system_key makes the same key in the same room the same NIVO line.
-- Data: no system line and no NIVO room existed when this was written, so neither statement meets a row it refuses.

ALTER TABLE public.chat_room_messages DROP CONSTRAINT chat_room_messages_ref_check;
ALTER TABLE public.chat_room_messages ADD CONSTRAINT chat_room_messages_ref_check CHECK (
    (kind = 'report' AND jsonb_typeof(ref) = 'object' AND ref ? 'run_id' AND (ref->>'run_id') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')
    OR (kind = 'approval' AND jsonb_typeof(ref) = 'object' AND ref ? 'decision_id' AND (ref->>'decision_id') ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$')
    OR (kind = 'text' AND author_kind = 'agent' AND jsonb_typeof(ref) = 'object' AND jsonb_typeof(ref->'agent_message') = 'string')
    OR (kind = 'text' AND author_kind = 'user' AND jsonb_typeof(ref) = 'object' AND jsonb_typeof(ref->'forwarded_from') = 'string' AND char_length(ref->>'forwarded_from') <= 200 AND (NOT ref ? 'agent_message' OR jsonb_typeof(ref->'agent_message') = 'string'))
    OR (kind IN ('text', 'system') AND ref IS NULL)
    OR (kind = 'system' AND author_kind = 'system' AND jsonb_typeof(ref) = 'object' AND ref ? 'agent_message' AND jsonb_typeof(ref->'agent_message') = 'string'));

-- one NIVO line per key in a room: a retried report of the same failure episode writes nothing new
CREATE UNIQUE INDEX chat_room_messages_system_key ON public.chat_room_messages USING btree (room_id, client_id)
    WHERE author_kind = 'system' AND client_id IS NOT NULL;

-- ---- from 20261112015100_brain-facts-vectors.sql ----
-- brain-facts-vectors: forward-only; immutable once on origin/main. Expand only: two partial indexes on public.brain_facts, nothing else.
-- The vectors of the facts in force must reach EVERY fact, at any size of the truth graph (the owner loads thousands of facts at once):
-- 1. The timed sweep (tick `brain-upkeep`, `FactEmbeddingsService.sweep` / `refresh`) asks which workspaces hold a fact in force with no
--    vector, then reads those facts in keyset pages by id:
--      SELECT DISTINCT workspace_id FROM brain_facts WHERE status = 'active' AND embedding IS NULL LIMIT 50
--      SELECT ... FROM brain_facts WHERE workspace_id = $1 AND status = 'active' AND embedding IS NULL AND id > $2 ORDER BY id LIMIT 128
--    brain_facts_active_unembedded holds only the rows still waiting for a vector, in (workspace_id, id) order: both reads touch nothing
--    else, and the index empties as the facts get their vectors. (Before, the refresh read the 500 oldest facts in force and compared
--    hashes in memory, so a workspace with more than 500 facts in force could leave its newest fact without a vector forever.)
-- 2. A fact whose line another row already holds takes that row's vector with no embedding call (`BrainFactEmbeddingsService.adopt`):
--      ... WHERE s.workspace_id = $1 AND s.embedding IS NOT NULL AND s.embedding_model = $2 AND s.embedding_dimensions = $3
--          AND s.embedding_hash = $4 ORDER BY s.id LIMIT 1
--    brain_facts_embedding_model (workspace_id, embedding_model) made this a scan of every embedded row of the workspace, once per fact;
--    brain_facts_embedding_hash makes it one index probe.
-- Data: no row changes; CREATE INDEX on dev's few hundred rows takes milliseconds.

CREATE INDEX brain_facts_active_unembedded ON public.brain_facts USING btree (workspace_id, id) WHERE ((status = 'active'::text) AND (embedding IS NULL));
CREATE INDEX brain_facts_embedding_hash ON public.brain_facts USING btree (workspace_id, embedding_hash) WHERE (embedding IS NOT NULL);

-- ---- from 20261112015200_brain-facts-words.sql ----
-- brain-facts-words: forward-only; immutable once on origin/main. Expand only: one partial GIN index on public.brain_facts, nothing else.
-- The word search of the truth graph (`BrainFactsReadService.wordHits`, behind `nivo.brain.search`, `knowledge-recall`, the setup turn
-- and the contract setup) read only the newest 500 facts in force and matched words in memory, so with thousands of facts in force an
-- older truth asked by its words alone ("mã số thuế") was never found. It now asks the database first, with the lens in SQL:
--   SELECT ... FROM brain_facts f
--   WHERE f.workspace_id = $1 AND f.status IN ('active', 'scheduled')
--     AND to_tsvector('simple'::regconfig, regexp_replace(public.knowledge_fold(f.subject_key || ' ' || f.attribute || ' ' || f.value),
--         '[^a-z0-9]+', ' ', 'g')) @@ to_tsquery('simple'::regconfig, $2)          -- $2 = 'phi | ship | noi | thanh'
--     AND (f.installation_id IS NULL OR f.installation_id = $3) AND (f.scope <> 'restricted' OR $4 = ANY(f.modules))
--   ORDER BY ts_rank(<same expression>, <same query>) DESC, f.updated_at DESC LIMIT 200
-- The indexed text is the one the in-memory score reads (subject key, attribute key, value), folded by the database's own
-- `public.knowledge_fold` (lower case + unaccent, the fold the passage index `knowledge_chunks.fts` uses), so "Phí ship" and "phi ship",
-- "đ" and "d" are the same words; every other run of characters becomes one space, so "30.000" is the words "30" and "000" as in
-- `factSlugOf`. The expression is the constant `FACT_WORDS_SQL` of brain-facts-read.service.ts; the spec checks both stay identical.
-- Partial on the two statuses served, so proposals and history never enter it. Data: no row changes; dev holds a few hundred rows.

CREATE INDEX brain_facts_words ON public.brain_facts USING gin (to_tsvector('simple'::regconfig, regexp_replace(public.knowledge_fold(subject_key || ' ' || attribute || ' ' || value), '[^a-z0-9]+', ' ', 'g'))) WHERE (status = ANY (ARRAY['active'::text, 'scheduled'::text]));

-- ---- from 20261112015300_mcp-call-log-truth-reads.sql ----
-- mcp-call-log-truth-reads: forward-only; immutable once on origin/main. Expand only: two nullable columns and one partial index on
-- public.mcp_call_log, nothing else.
-- concept.agent-knowledge: "Every decision records the knowledge line and the source it used". The audit line of every MCP gateway call
-- (`McpGatewayService.audit`) already exists per call; it now also keeps
--   run_id      the run (agent turn) the call was made in (`GatewayCaller.turnId`: a node step's run token names its run), null otherwise;
--   fact_reads  for a read of the truth graph (`nivo.brain.search`, `fact.list`, `fact.get`, `fact.related`), the truths it served as
--               `[{"factId": "<uuid>", "version": 3}, ...]` (ids and versions only, at most 50), null for every other call.
-- The run page reads them per run (`McpCallLogService.truthReadsOfRun`):
--   SELECT id, tool, created_at, fact_reads FROM mcp_call_log
--   WHERE workspace_id = $1 AND run_id = $2 AND fact_reads IS NOT NULL ORDER BY created_at LIMIT 100
-- mcp_call_log_run_reads holds only the lines that kept reads, in (workspace_id, run_id, created_at) order.
-- run_id is text, not uuid: a caller's turn id is written as given and an unexpected shape can never fail the audit insert.
-- Data: no row changes; ADD COLUMN with no default rewrites nothing; dev holds a few hundred lines.
-- ORDER: the api, mcp and cli builds that carry this change write both columns on EVERY gateway call: apply this migration BEFORE
-- starting those builds, or every call's audit insert fails.

ALTER TABLE public.mcp_call_log ADD COLUMN run_id text;
ALTER TABLE public.mcp_call_log ADD COLUMN fact_reads jsonb;
CREATE INDEX mcp_call_log_run_reads ON public.mcp_call_log USING btree (workspace_id, run_id, created_at) WHERE (fact_reads IS NOT NULL);

-- ---- from 20261112015400_brain-limits.sql ----
-- brain-limits: forward-only; immutable once on origin/main. Expand only: three partial indexes on public.brain_facts, one on
-- public.brain_extractions, and one column on public.brain_source_critiques (nullable-safe default), nothing dropped or rewritten.
-- Nothing is dropped silently at any size of the truth graph (BRAIN-LIMITS, 2026-11-11):
-- 1. The derive pass of the policy layer pages over the truths that need a look only, keyset by truth key
--    (`BrainPolicyCandidatesService.page`):
--      SELECT DISTINCT f.subject_key, f.attribute, COALESCE(f.installation_id, '0000…'::uuid) FROM brain_facts f
--      WHERE f.workspace_id = $1 AND f.status IN ('active','scheduled') AND f.proposal_kind = 'set' AND f.subject_type NOT IN (…)
--        AND (key) > ($2,$3,$4) AND NOT EXISTS (… brain_policies bound to a held fact …) ORDER BY 1,2,3 LIMIT 200
--    brain_facts_held_truth holds the held rows in truth-key order: the page reads forward from the cursor instead of scanning the
--    workspace (before, every pass read the newest 2,000 facts and planned in memory: truths past 2,000 were never judged).
-- 2. The Second Brain page lists facts in keyset pages (`BrainFactsPagingService.page`):
--      … WHERE f.workspace_id = $1 AND f.status IN (…) AND (f.updated_at, f.id) < ($2,$3) ORDER BY f.updated_at DESC, f.id DESC LIMIT n
--    brain_facts_page serves the order of every page whatever the statuses asked (before: the newest 2,000, the rest never shown).
-- 3. The upkeep tick resumes the readings that waited for credits (`BrainExtractionsService.blocked`, across workspaces):
--      SELECT … FROM brain_extractions WHERE status = 'blocked_credits' ORDER BY source_id LIMIT 50
--    brain_extractions_blocked holds only those rows.
-- 4. The document critic counts the passages of a document no finished critique reviewed (`waiting_passages`): the documents list and
--    the critique page say how many are withheld from customers BECAUSE they are unreviewed, never silently.
-- Data: no row changes; the column defaults to 0 (counted again at the next critique request); CREATE INDEX on dev's few hundred rows
-- takes milliseconds.

CREATE INDEX brain_facts_held_truth ON public.brain_facts USING btree (workspace_id, subject_key, attribute, COALESCE(installation_id, '00000000-0000-0000-0000-000000000000'::uuid)) WHERE (status = ANY (ARRAY['active'::text, 'scheduled'::text]));
CREATE INDEX brain_facts_page ON public.brain_facts USING btree (workspace_id, updated_at DESC, id DESC) WHERE (status = ANY (ARRAY['active'::text, 'proposed'::text, 'scheduled'::text]));
CREATE INDEX brain_extractions_blocked ON public.brain_extractions USING btree (source_id) WHERE (status = 'blocked_credits'::text);
ALTER TABLE public.brain_source_critiques ADD COLUMN waiting_passages integer DEFAULT 0 NOT NULL;

-- ---- from 20261112015500_ingest-two-paths.sql ----
-- ingest-two-paths: forward-only; immutable once on origin/main. Expand only: new nullable columns, one widened check, one partial index.
-- Owner's decision 2026-11-11 (concept truth-graph, extensions.ingestionTwoPaths): a document is stored, cut into passages and indexed for
-- search, nothing else; the truths are indexed OUT of it: a cheap triage marks the passages that state a rule of the shop and only those
-- are read into truths.
--
-- 1. knowledge_chunks (one row = one passage):
--    text_hash       what the passage says, whatever model embedded it: hex sha256 of its normalised text (`passageTextHashOf`). The
--                    stored content is already normalised, so the backfill below computes the same value the back end writes. A truth read
--                    from a document names its passage by this hash (evidence.chunkHash).
--    triage          the verdict of the triage pass: rule (states how the shop works: read into truths), data (records: catalogue rows,
--                    orders, stock; shop data, never truths), none. NULL = not judged yet.
--    triage_version  the triage prompt version that judged it (0 = judged by code, no model). A prompt change re-judges only the passages
--                    of another version.
--    truths_version  the extraction prompt version that read the passage into truths; NULL = not read.
--    indexed_at      when the passage's vector was accepted by the vector index: the passage is searchable by MEANING from then on (by
--                    words it is searchable as soon as the row exists). Owner 2026-11-11: the vector store is Qdrant, mapped one to one
--                    to these rows, and Postgres stays the system of record: this migration adds NO vector column and NO vector index.
--                    Per passage Postgres keeps what the vector stands for (content_hash = text + model, embedding_model) and this time.
--                    Backfilled from the rows that hold a vector today.
--    No new index: every read of these columns is one document's passages by knowledge_chunks_source (source_id, ord), and a document
--    holds at most 120,000 characters (a few hundred passages).
-- 2. brain_extractions (one row per document: where its truths stand):
--    stage                                  triage | extract | settle while the status is running, parked or failed.
--    passages_total / _triaged / _kept      the document's passages, how many are judged, how many state a rule.
--    facts_applied / _asked / _waiting      truths put in force directly, truths the founder is asked about (a contradiction), truths that
--                                           wait (another uploader than the founder, or the ceiling).
--    status + awaiting_critique             the truths are filed and wait for the critic's verdict on their passages (nothing in force yet).
--    status + at_ceiling                    the business holds its ceiling of truths in force: the rest wait as proposals.
--    brain_extractions_parked               the upkeep tick reads the readings that wait (credits, critic, ceiling) across workspaces, oldest
--                                           first; both states are rare, so the index stays a few rows.

ALTER TABLE public.knowledge_chunks ADD COLUMN text_hash text;
ALTER TABLE public.knowledge_chunks ADD COLUMN triage text;
ALTER TABLE public.knowledge_chunks ADD COLUMN triage_version integer;
ALTER TABLE public.knowledge_chunks ADD COLUMN truths_version integer;
ALTER TABLE public.knowledge_chunks ADD COLUMN indexed_at timestamptz;
ALTER TABLE public.knowledge_chunks
    ADD CONSTRAINT knowledge_chunks_triage_check CHECK (triage IS NULL OR triage = ANY (ARRAY['rule'::text, 'data'::text, 'none'::text]));
COMMENT ON COLUMN public.knowledge_chunks.text_hash IS 'Hex sha256 of the normalised passage text, independent of the embedding model.';
COMMENT ON COLUMN public.knowledge_chunks.triage IS 'Triage verdict: rule (read into truths), data (shop records, never truths), none; NULL = not judged.';

UPDATE public.knowledge_chunks SET text_hash = encode(sha256(convert_to(content, 'UTF8')), 'hex') WHERE text_hash IS NULL;
UPDATE public.knowledge_chunks SET indexed_at = updated_at WHERE embedding IS NOT NULL AND indexed_at IS NULL;

ALTER TABLE public.brain_extractions ADD COLUMN stage text;
ALTER TABLE public.brain_extractions ADD COLUMN passages_total integer NOT NULL DEFAULT 0;
ALTER TABLE public.brain_extractions ADD COLUMN passages_triaged integer NOT NULL DEFAULT 0;
ALTER TABLE public.brain_extractions ADD COLUMN passages_kept integer NOT NULL DEFAULT 0;
ALTER TABLE public.brain_extractions ADD COLUMN facts_applied integer NOT NULL DEFAULT 0;
ALTER TABLE public.brain_extractions ADD COLUMN facts_asked integer NOT NULL DEFAULT 0;
ALTER TABLE public.brain_extractions ADD COLUMN facts_waiting integer NOT NULL DEFAULT 0;
ALTER TABLE public.brain_extractions
    ADD CONSTRAINT brain_extractions_stage_check CHECK (stage IS NULL OR stage = ANY (ARRAY['triage'::text, 'extract'::text, 'settle'::text]));

ALTER TABLE public.brain_extractions DROP CONSTRAINT brain_extractions_status_check;
ALTER TABLE public.brain_extractions
    ADD CONSTRAINT brain_extractions_status_check
    CHECK (status = ANY (ARRAY['queued'::text, 'running'::text, 'done'::text, 'failed'::text, 'blocked_credits'::text, 'awaiting_critique'::text, 'at_ceiling'::text]));

CREATE INDEX brain_extractions_parked ON public.brain_extractions USING btree (updated_at)
    WHERE (status = ANY (ARRAY['blocked_credits'::text, 'awaiting_critique'::text, 'at_ceiling'::text]));

-- ---- from 20261112015600_vector-index-sync.sql ----
-- vector-index-sync: forward-only; immutable once on origin/main. Expand only: one nullable column, one partial index, one new table.
-- Owner's decision 2026-11-11 (concept truth-graph, extensions.vectorStoreQdrant): the vectors live in Qdrant, mapped one to one to
-- Postgres rows (the point id is the row id); Postgres stays the system of record. This migration adds what Postgres keeps of a
-- point and where the reconcile stands. It adds NO vector column and drops nothing: the pgvector columns stay until the contract
-- half (kept out of this folder until the live checks pass) drops them.
--
-- 1. brain_facts.indexed_at          when the vector index accepted the vector of the fact's line (with embedding_model and
--                                    embedding_hash, written in the same statement by FactVectorRowsService.stamp). knowledge_chunks
--                                    has the same column from 20261112015500. NULL = no point accepted yet.
--    brain_facts_indexed_hash        the adoption probe: "another row of the workspace whose point holds the vector of this line"
--                                      SELECT id, embedding_hash FROM brain_facts
--                                       WHERE workspace_id = $1 AND embedding_hash = ANY($2) AND indexed_at IS NOT NULL
--                                         AND embedding_model = $3 AND status IN ('active','proposed') ORDER BY id LIMIT 500
--                                    one index range per hash; the index holds only rows the index accepted.
-- 2. vector_sync_state               one row per kind of point (passage, truth) for the whole deployment: the cursors of the two
--                                    walks of the reconcile (rows by id, points by the index's page cursor), how many passes ended,
--                                    and the drift episode (consecutive runs that could not repair, when it began). No workspace
--                                    column: the reconcile is the deployment's, like job_ticks; the same policy shape as job_ticks.
-- Data: no row is rewritten. brain_facts.indexed_at stays NULL for every existing fact: its point does not exist yet, and the first
-- runs of the reconcile create it from the pgvector column (no embedding call) and stamp the row.

ALTER TABLE public.brain_facts ADD COLUMN indexed_at timestamptz;
COMMENT ON COLUMN public.brain_facts.indexed_at IS 'When the vector index accepted the vector of the fact''s line; NULL = no point yet.';

CREATE INDEX brain_facts_indexed_hash ON public.brain_facts USING btree (workspace_id, embedding_hash) WHERE (indexed_at IS NOT NULL);

CREATE TABLE public.vector_sync_state (
    kind text NOT NULL PRIMARY KEY,
    rows_after uuid,
    points_after text,
    passes integer DEFAULT 0 NOT NULL,
    drift_runs integer DEFAULT 0 NOT NULL,
    drift_since timestamptz,
    last_run_at timestamptz,
    created_at timestamptz DEFAULT now() NOT NULL,
    updated_at timestamptz DEFAULT now() NOT NULL,
    CONSTRAINT vector_sync_state_kind_check CHECK ((kind = ANY (ARRAY['passage'::text, 'truth'::text])))
);

CREATE TRIGGER vector_sync_state_set_updated_at BEFORE UPDATE ON public.vector_sync_state FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

ALTER TABLE public.vector_sync_state ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.vector_sync_state FORCE ROW LEVEL SECURITY;
CREATE POLICY vector_sync_state_app_be_select ON public.vector_sync_state FOR SELECT TO app_be USING ((kind IS NOT NULL));
CREATE POLICY vector_sync_state_app_be_insert ON public.vector_sync_state FOR INSERT TO app_be WITH CHECK ((kind IS NOT NULL));
CREATE POLICY vector_sync_state_app_be_update ON public.vector_sync_state FOR UPDATE TO app_be USING ((kind IS NOT NULL)) WITH CHECK ((kind IS NOT NULL));
REVOKE ALL ON TABLE public.vector_sync_state FROM PUBLIC, anon, authenticated;
GRANT SELECT, INSERT, UPDATE ON TABLE public.vector_sync_state TO app_be;

-- ---- from 20261112015900_engine-fix-wake-due-order-credits.sql ----
-- engine-fix-wake-due-order-credits: forward-only; immutable once on origin/main. Expand only: one function replaced (same signature,
-- same grants), one unique index replaced by a plain index on the same expression. Safe before or after the back end that reads it: an
-- older back end already schedules a follow-up drain on an `idle` answer that carries `waitMs`, and nothing reads the unique index.
--
-- 1. agent_turn_begin (D-MX-5, matrix walk 2026-11-11: a stop's resume wake and a care-timer wake waited 94-120 s for the minute sweep).
--    A wake's `not_before` is its writer's transaction time; its drain job runs right after the commit. On dev the database clock is
--    stepped back by the container VM's time sync (job_outbox shows 231 of 4590 jobs of 2026-11-11 STARTED before their own row was
--    CREATED; the resume wake c2e14a86 was written at 09:17:27.77 by the database clock while the api logged it at 09:17:26.63, and its
--    turn began at 09:19:00.81 by the api clock / 09:19:00.19 by the database's). The drain then read a now() earlier than the wake's
--    not_before, found nothing due and answered a plain `idle` (the burst gate's wait applies to conversation scopes only), and nothing
--    else was coming until the sweep. The gate now also answers `waitMs` / `waitFor` when the next pending wake of the scope is due
--    within two minutes, and the caller (AgentDrainService.rearm) schedules one follow-up drain for that moment, as it does for a burst.
--    The lease, the fence and which wake runs are untouched.
--
-- 2. records_payment_transaction_order_key -> records_payment_transaction_order (D-MX-3, matrix walk TWO: a customer paid an order in two
--    credits; the second could never be tied to the order, so it stayed `unmatched` with no ledger line and the paid card showed half).
--    An order may be paid by several credits: blocks-core `payment.transaction` declares the index `order` (orderId, id desc) in place of
--    the unique key. A second settlement of a paid order is still refused by the settle rule (the order no longer waits) and by the
--    order's own version; a credit tied to another order is refused by the executor (`transaction_used`).

CREATE OR REPLACE FUNCTION public.agent_turn_begin(p_agent uuid, p_scope text, p_owner text, p_lease_s integer, p_window_ms integer, p_max_ms integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_workspace uuid;
  v_lease public.agent_work_leases%ROWTYPE;
  v_wake public.agent_wakes%ROWTYPE;
  v_turn_id uuid;
  v_proposal jsonb;
  v_fence bigint;
  v_ended jsonb := '[]'::jsonb;
  v_merged text;
  v_context jsonb;
  v_window integer;
  v_max integer;
  v_newest_id uuid;
  v_newest_at timestamptz;
  v_open timestamptz;
  v_due_id uuid;
  v_due_at timestamptz;
BEGIN
  SELECT a.workspace_id INTO v_workspace FROM public.agents a WHERE a.id = p_agent;
  IF v_workspace IS NULL THEN
    RETURN jsonb_build_object('result', 'idle', 'ended', v_ended);
  END IF;
  INSERT INTO public.agent_work_state (agent_id, workspace_id) VALUES (p_agent, v_workspace) ON CONFLICT (agent_id) DO NOTHING;
  IF public.agent_work_is_off(p_agent, v_workspace) THEN
    WITH held AS (
      UPDATE public.agent_wakes w SET status = 'held', reason = 'killed'
       WHERE w.agent_id = p_agent AND w.scope_key = p_scope AND w.status = 'pending' RETURNING w.*
    )
    SELECT COALESCE(jsonb_agg(public.agent_wake_ended(ROW(h.*)::public.agent_wakes, 'held')), '[]'::jsonb) INTO v_ended FROM held h;
    -- A turn whose worker crashed before the switch is taken over here too, or its lease would lapse for the sweep to drain again every minute.
    SELECT * INTO v_lease FROM public.agent_work_leases l WHERE l.agent_id = p_agent AND l.scope_key = p_scope FOR UPDATE;
    IF FOUND AND v_lease.running_turn_id IS NOT NULL AND v_lease.lease_until <= now() THEN
      UPDATE public.agent_turns t SET status = 'abandoned' WHERE t.id = v_lease.running_turn_id AND t.status IN ('running', 'proposed');
      WITH crashed AS (
        UPDATE public.agent_wakes w SET status = 'held', reason = 'killed'
         WHERE w.status = 'running' AND w.id = (SELECT t.wake_id FROM public.agent_turns t WHERE t.id = v_lease.running_turn_id) RETURNING w.*
      )
      SELECT v_ended || COALESCE(jsonb_agg(public.agent_wake_ended(ROW(c.*)::public.agent_wakes, 'held')), '[]'::jsonb) INTO v_ended FROM crashed c;
      UPDATE public.agent_work_leases l SET running_turn_id = NULL, lease_until = NULL, lease_owner = NULL
       WHERE l.agent_id = p_agent AND l.scope_key = p_scope;
    END IF;
    RETURN jsonb_build_object('result', 'killed', 'ended', v_ended);
  END IF;
  INSERT INTO public.agent_work_leases (agent_id, scope_key, workspace_id) VALUES (p_agent, p_scope, v_workspace)
    ON CONFLICT (agent_id, scope_key) DO NOTHING;
  SELECT * INTO v_lease FROM public.agent_work_leases l WHERE l.agent_id = p_agent AND l.scope_key = p_scope FOR UPDATE;
  IF v_lease.running_turn_id IS NOT NULL AND v_lease.lease_until > now() THEN
    RETURN jsonb_build_object('result', 'busy');
  END IF;
  IF v_lease.running_turn_id IS NOT NULL THEN
    UPDATE public.agent_turns t SET status = 'abandoned' WHERE t.id = v_lease.running_turn_id AND t.status = 'running';
    UPDATE public.agent_wakes w SET status = 'pending', not_before = now()
     WHERE w.status = 'running' AND w.id = (SELECT t.wake_id FROM public.agent_turns t WHERE t.id = v_lease.running_turn_id);
  END IF;
  LOOP
    SELECT * INTO v_wake FROM public.agent_wakes w
     WHERE w.agent_id = p_agent AND w.scope_key = p_scope AND w.status = 'pending' AND w.not_before <= now()
     ORDER BY w.priority, w.created_at LIMIT 1 FOR UPDATE;
    IF NOT FOUND THEN
      UPDATE public.agent_work_leases l SET running_turn_id = NULL, lease_until = NULL, lease_owner = NULL
       WHERE l.agent_id = p_agent AND l.scope_key = p_scope;
      -- D-MX-5: a drain that came before the next pending wake of the scope is due by THIS clock (its not_before is the writer's
      -- transaction time, and the database clock of a container VM is stepped back by its time sync: a drain that runs right after the
      -- commit can read a now() that is earlier than the wake's own timestamp) is told how long is left and for which wake, like the
      -- burst gate below, and the caller schedules one follow-up drain. Only for a wake due within two minutes: a later one is a planned
      -- wait (a retry) that its own drain or the minute sweep serves.
      SELECT w.id, w.not_before INTO v_due_id, v_due_at FROM public.agent_wakes w
       WHERE w.agent_id = p_agent AND w.scope_key = p_scope AND w.status = 'pending'
         AND w.not_before > now() AND w.not_before <= now() + interval '120 seconds'
       ORDER BY w.not_before, w.id LIMIT 1;
      IF v_due_id IS NOT NULL THEN
        RETURN jsonb_build_object(
          'result', 'idle',
          'ended', v_ended,
          'waitMs', greatest(1, ceil(extract(epoch FROM (v_due_at - now())) * 1000))::integer,
          'waitFor', v_due_id
        );
      END IF;
      RETURN jsonb_build_object('result', 'idle', 'ended', v_ended);
    END IF;
    EXIT WHEN v_wake.attempts < v_wake.max_attempts;
    UPDATE public.agent_wakes w SET status = 'dead', reason = 'attempts', finished_at = now() WHERE w.id = v_wake.id;
    v_ended := v_ended || jsonb_build_array(public.agent_wake_ended(v_wake, 'dead'));
  END LOOP;
  -- The sliding burst window: a wake of a conversation scope waits while the newest pending wake of the scope is inside the window (less
  -- half a second, so a drain that is a little early still runs), so every new message extends the wait by the window; a burst whose first
  -- message is older than p_max_ms stops waiting. When the turn runs it takes every pending wake of the scope into one.
  -- A drain that is told to wait is told for how long, on THIS clock, and for which wake: `waitMs` and `waitFor` ride on the idle answer.
  -- The caller schedules one drain that far ahead. The delay of a drain is measured by the broker on another machine's clock, and a
  -- clock that is stepped while the drain waits brings it here early; an early drain that only went away left the wake to the minute sweep.
  v_window := COALESCE(v_wake.burst_window_ms, p_window_ms);
  v_max := COALESCE(v_wake.burst_max_ms, p_max_ms);
  IF v_window > 0 AND p_scope LIKE 'conversation:%' THEN
    SELECT w.id, w.created_at INTO v_newest_id, v_newest_at FROM public.agent_wakes w
     WHERE w.agent_id = p_agent AND w.scope_key = p_scope AND w.status = 'pending'
     ORDER BY w.created_at DESC, w.id DESC LIMIT 1;
    -- The moment the wait ends: the window after the newest message, or the longest wait after the first, whichever comes first.
    v_open := least(
      v_newest_at + make_interval(secs => greatest(v_window - 500, 0) / 1000.0),
      v_wake.created_at + make_interval(secs => greatest(v_max, v_window) / 1000.0)
    );
    IF v_open > now() THEN
      RETURN jsonb_build_object(
        'result', 'idle',
        'ended', v_ended,
        'waitMs', greatest(1, ceil(extract(epoch FROM (v_open - now())) * 1000))::integer,
        'waitFor', v_newest_id
      );
    END IF;
    WITH merged AS (
      UPDATE public.agent_wakes w SET status = 'skipped', reason = 'coalesced', finished_at = now()
       WHERE w.agent_id = p_agent AND w.scope_key = p_scope AND w.status = 'pending'
         AND w.id <> v_wake.id AND w.not_before <= now()
       RETURNING w.created_at, w.context ->> 'messageId' AS message_id
    )
    SELECT string_agg(m.message_id, ',' ORDER BY m.created_at) INTO v_merged FROM merged m WHERE m.message_id IS NOT NULL;
    IF v_merged IS NOT NULL THEN
      UPDATE public.agent_wakes w SET context = w.context || jsonb_build_object('mergedMessageIds', v_merged)
        WHERE w.id = v_wake.id RETURNING w.context INTO v_context;
    END IF;
  END IF;
  UPDATE public.agent_wakes w SET status = 'running', attempts = w.attempts + 1, started_at = COALESCE(w.started_at, now())
   WHERE w.id = v_wake.id;
  v_fence := v_lease.fence + 1;
  SELECT t.id, t.proposal INTO v_turn_id, v_proposal FROM public.agent_turns t
   WHERE t.wake_id = v_wake.id AND t.status = 'proposed' ORDER BY t.fence DESC LIMIT 1;
  IF v_turn_id IS NULL THEN
    INSERT INTO public.agent_turns (workspace_id, agent_id, wake_id, fence, status)
      VALUES (v_workspace, p_agent, v_wake.id, v_fence, 'running') RETURNING id INTO v_turn_id;
  ELSE
    UPDATE public.agent_turns t SET fence = v_fence WHERE t.id = v_turn_id;
  END IF;
  UPDATE public.agent_work_leases l
     SET fence = v_fence, lease_owner = p_owner, lease_until = now() + make_interval(secs => p_lease_s), running_turn_id = v_turn_id
   WHERE l.agent_id = p_agent AND l.scope_key = p_scope;
  RETURN jsonb_build_object(
    'result', 'begun',
    'workspaceId', v_workspace,
    'fence', v_fence,
    'turnId', v_turn_id,
    'wakeId', v_wake.id,
    'source', v_wake.source,
    'eventKey', v_wake.event_key,
    'context', coalesce(v_context, v_wake.context),
    'actorMemberId', v_wake.actor_member_id,
    'attempts', v_wake.attempts + 1,
    'maxAttempts', v_wake.max_attempts,
    'wakeCreatedAt', v_wake.created_at,
    'proposal', v_proposal,
    'ended', v_ended
  );
END;
$$;
REVOKE ALL ON FUNCTION public.agent_turn_begin(uuid, text, text, integer, integer, integer) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.agent_turn_begin(uuid, text, text, integer, integer, integer) TO app_be;


-- create_index public.records_payment_transaction:index:records_payment_transaction_order: on workspace_id, data->>'orderid', iddesc using btree
CREATE INDEX IF NOT EXISTS "records_payment_transaction_order" ON public."records_payment_transaction" USING btree (workspace_id, ((data->>'orderId')::uuid), id DESC);
DROP INDEX IF EXISTS public."records_payment_transaction_order_key";

-- ---- from 20261112020000_ai-usage-work-call-facts.sql ----
-- ai-usage-work-call-facts: forward-only; immutable once on origin/main. Expand only: one function replaced (same signature, same
-- grants). Safe before or after the back end that sends the new keys: an older back end sends none and the columns stay null as today.
--
-- Restart FOUR (2026-11-11): the derive pass's three model calls logged `finish: end_turn` but their `ai_usage_events.finish_reason`
-- was null. The knowledge meter (UsageMeterService) books through `record_ai_usage_work`, which wrote the run, work, try and time of a
-- call but never the two call facts migration 012200 added to the table: the upstream that served it and why the model stopped. The
-- writer now takes them from the same facts object (`upstream`, `finish_reason`), cut to the columns' checks like every other fact.

CREATE OR REPLACE FUNCTION public.record_ai_usage_work(p_workspace uuid, p_kind text, p_module text, p_model text, p_prompt integer, p_completion integer, p_cost numeric, p_estimated boolean, p_facts jsonb) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  insert into public.ai_usage_events (
    workspace_id, kind, module, model, prompt_tokens, completion_tokens, cost_usd, estimated,
    run_id, work_kind, work_ref, step_key, agent_id, failure, try_number, duration_ms, purpose, upstream, finish_reason
  )
  values (
    p_workspace, p_kind, p_module, p_model, greatest(p_prompt, 0), greatest(p_completion, 0), greatest(p_cost, 0), p_estimated,
    nullif(p_facts->>'run_id', '')::uuid,
    left(nullif(p_facts->>'work_kind', ''), 40),
    left(nullif(p_facts->>'work_ref', ''), 200),
    left(nullif(p_facts->>'step_key', ''), 120),
    nullif(p_facts->>'agent_id', '')::uuid,
    left(nullif(p_facts->>'failure', ''), 40),
    case when (p_facts->>'try_number') ~ '^[0-9]{1,2}$' and (p_facts->>'try_number')::int between 1 and 10
         then (p_facts->>'try_number')::smallint end,
    case when (p_facts->>'duration_ms') ~ '^[0-9]{1,9}$' then (p_facts->>'duration_ms')::int end,
    left(nullif(p_facts->>'purpose', ''), 200),
    left(nullif(btrim(p_facts->>'upstream'), ''), 120),
    left(nullif(btrim(p_facts->>'finish_reason'), ''), 40)
  );
$$;
REVOKE EXECUTE ON FUNCTION public.record_ai_usage_work(p_workspace uuid, p_kind text, p_module text, p_model text, p_prompt integer, p_completion integer, p_cost numeric, p_estimated boolean, p_facts jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.record_ai_usage_work(p_workspace uuid, p_kind text, p_module text, p_model text, p_prompt integer, p_completion integer, p_cost numeric, p_estimated boolean, p_facts jsonb) TO app_be;

-- ---- from 20261112020500_workspace-enterprise-key.sql ----
-- workspace-enterprise-key: forward-only; immutable once on origin/main. Expand only: one nullable column on public.workspaces, one
-- check and one partial unique index; no row changes, nothing dropped or rewritten.
-- An ordinary workspace is identified by its uuid alone. An ENTERPRISE workspace additionally carries ONE string identifier
-- (`nivo-web`): unique across the platform, a lowercase slug, NULL for every ordinary workspace. The uuid stays the primary key of
-- everything (routes, foreign keys, row security, tokens): the string is an additional name and no read resolves a workspace by it.
-- It decides which PRIVATE plugins a workspace may see, install and run: a private plugin names the enterprise identifiers it belongs
-- to (`definePlugin({ visibility: "private", enterprises: ["nivo-web"] })`), and `WorkspaceEnterpriseService.opens` compares.
-- Written only by the seed and by the platform admin (`adminSetWorkspaceEnterpriseKey`); no door of the workspace's own owner or
-- manager writes it. The app reads it with an explicit select (the entity column is `select: false`):
--   SELECT enterprise_key FROM public.workspaces WHERE id = $1
--   SELECT id FROM public.workspaces WHERE enterprise_key = $1           -- the uniqueness check before a write; served by the index
-- Data: every existing row keeps NULL (an ordinary workspace). ADD COLUMN without a default rewrites nothing.

ALTER TABLE public.workspaces ADD COLUMN enterprise_key text;
ALTER TABLE public.workspaces ADD CONSTRAINT workspaces_enterprise_key_shape CHECK ((enterprise_key IS NULL) OR ((char_length(enterprise_key) <= 40) AND (enterprise_key ~ '^[a-z][a-z0-9]*(-[a-z0-9]+)*$'::text)));
CREATE UNIQUE INDEX workspaces_enterprise_key ON public.workspaces USING btree (enterprise_key) WHERE (enterprise_key IS NOT NULL);

-- ---- from 20261112020600_data-read-cursors.sql ----
-- data-read-cursors: forward-only; immutable once on origin/main. Expand only: one new table, nothing else touched.
-- How far an agent has READ the hub rows of one connection (P2 of NIVO Web, mail triage: "an agent reads mail and reports the mails that
-- need attention"). `nivo.mail.message.list` hands an agent the mails of an attached mailbox that arrived in the hub after this point
-- and moves the point to the last one it handed over, so a scheduled workflow reads each mail once without any engine memory. One row
-- per agent, connection and hub entity. The point (`seen_through`) is `<created_at of the hub row, ISO with microseconds>~<hub row id>`: the order in
-- which rows first entered the hub (an upsert never changes `data_records.created_at`). Nothing of a mail is stored here: no address, no
-- subject, no text. The mailbox itself is never written (IMAP stays read-only); this is NIVO's own bookkeeping.

CREATE TABLE public.data_read_cursors (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,
    agent_id uuid NOT NULL REFERENCES public.agents(id) ON DELETE CASCADE,
    connection_id uuid NOT NULL REFERENCES public.connections(id) ON DELETE CASCADE,
    entity text NOT NULL,
    seen_through text NOT NULL,
    created_at timestamptz DEFAULT now() NOT NULL,
    updated_at timestamptz DEFAULT now() NOT NULL,
    CONSTRAINT data_read_cursors_entity_check CHECK ((entity = ANY (ARRAY['customer'::text, 'order'::text, 'product'::text, 'transaction'::text, 'message'::text, 'document'::text, 'other'::text]))),
    CONSTRAINT data_read_cursors_seen_through_check CHECK ((char_length(seen_through) BETWEEN 1 AND 100)),
    CONSTRAINT data_read_cursors_reader_unique UNIQUE (agent_id, connection_id, entity)
);

-- The positions of one agent over the connections of a workspace (one read names the agent and its attached connections).
CREATE INDEX data_read_cursors_agent ON public.data_read_cursors USING btree (workspace_id, agent_id, entity);

CREATE TRIGGER data_read_cursors_set_updated_at BEFORE UPDATE ON public.data_read_cursors FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

ALTER TABLE public.data_read_cursors ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.data_read_cursors FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE ON TABLE public.data_read_cursors TO app_be;
CREATE POLICY data_read_cursors_app_be_select ON public.data_read_cursors FOR SELECT TO app_be USING ((workspace_id IS NOT NULL));
CREATE POLICY data_read_cursors_app_be_insert ON public.data_read_cursors FOR INSERT TO app_be WITH CHECK ((workspace_id IS NOT NULL));
CREATE POLICY data_read_cursors_app_be_update ON public.data_read_cursors FOR UPDATE TO app_be USING ((workspace_id IS NOT NULL)) WITH CHECK ((workspace_id IS NOT NULL));

-- ---- from 20261112020800_extract-fix-window-notes.sql ----
-- extract-fix-window-notes: forward-only; immutable once on origin/main. Expand only: three new columns with constant defaults and their
-- checks on brain_extractions, one function replaced (same signature, same grants). Safe before or after the back end that uses them only
-- in this order: APPLY BEFORE the build (the entity selects the new columns). An older back end never reads them.
--
-- Brain walk 2 (2026-11-11, D-N-10 / D-N-11 / D-N-8):
-- 1. brain_extractions (one row per document: where its truths stand):
--    windows_skipped   reading calls (windows of up to four rule passages) whose answer could not be read even after one follow-up
--                      with a changed prompt: the window is SKIPPED, never fatal to the part, and its passages are read again by the
--                      next reading of the document. Shown on the documents page ("n calls skipped").
--    lines_refused     answer lines not kept (not eight fields, or a value its passage does not hold) over the reading.
--    answer_notes      the last 20 refused or skipped answers of the reading, as {at, reason, passages, refused, answer}: `answer` is the
--                      model's raw reply cut to 1,000 characters. It may quote the document (customer names in a chat export), so it is
--                      kept HERE, in the tenant's own row that is deleted with the document (FK cascade from knowledge_sources), and
--                      never in a log line (BE-LOGGING-2: no request body or personal identifier is logged).
-- 2. record_ai_usage_work: the knowledge meter's writer now also books the cache and reasoning counts of a call: cached_tokens (prompt
--    tokens read from the provider's cache), cache_write_tokens (written to it), reasoning_tokens. Migration 020000 (was 016000) added the upstream and
--    the finish reason; cached tokens were still never written (0 of 5,661 rows on dev, although the cost was discounted). Each count is
--    clamped to the table's checks (cached_tokens <= prompt_tokens, reasoning_tokens <= completion_tokens).

ALTER TABLE public.brain_extractions ADD COLUMN windows_skipped integer NOT NULL DEFAULT 0;
ALTER TABLE public.brain_extractions ADD COLUMN lines_refused integer NOT NULL DEFAULT 0;
ALTER TABLE public.brain_extractions ADD COLUMN answer_notes jsonb NOT NULL DEFAULT '[]'::jsonb;
ALTER TABLE public.brain_extractions
    ADD CONSTRAINT brain_extractions_windows_skipped_check CHECK (windows_skipped >= 0);
ALTER TABLE public.brain_extractions
    ADD CONSTRAINT brain_extractions_lines_refused_check CHECK (lines_refused >= 0);
ALTER TABLE public.brain_extractions
    ADD CONSTRAINT brain_extractions_answer_notes_check CHECK (jsonb_typeof(answer_notes) = 'array');
COMMENT ON COLUMN public.brain_extractions.answer_notes IS 'Last 20 refused or skipped model answers of the reading (raw reply cut to 1,000 chars): tenant data, deleted with the document, never logged.';

CREATE OR REPLACE FUNCTION public.record_ai_usage_work(p_workspace uuid, p_kind text, p_module text, p_model text, p_prompt integer, p_completion integer, p_cost numeric, p_estimated boolean, p_facts jsonb) RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  insert into public.ai_usage_events (
    workspace_id, kind, module, model, prompt_tokens, completion_tokens, cost_usd, estimated,
    run_id, work_kind, work_ref, step_key, agent_id, failure, try_number, duration_ms, purpose, upstream, finish_reason,
    cached_tokens, cache_write_tokens, reasoning_tokens
  )
  values (
    p_workspace, p_kind, p_module, p_model, greatest(p_prompt, 0), greatest(p_completion, 0), greatest(p_cost, 0), p_estimated,
    nullif(p_facts->>'run_id', '')::uuid,
    left(nullif(p_facts->>'work_kind', ''), 40),
    left(nullif(p_facts->>'work_ref', ''), 200),
    left(nullif(p_facts->>'step_key', ''), 120),
    nullif(p_facts->>'agent_id', '')::uuid,
    left(nullif(p_facts->>'failure', ''), 40),
    case when (p_facts->>'try_number') ~ '^[0-9]{1,2}$' and (p_facts->>'try_number')::int between 1 and 10
         then (p_facts->>'try_number')::smallint end,
    case when (p_facts->>'duration_ms') ~ '^[0-9]{1,9}$' then (p_facts->>'duration_ms')::int end,
    left(nullif(p_facts->>'purpose', ''), 200),
    left(nullif(btrim(p_facts->>'upstream'), ''), 120),
    left(nullif(btrim(p_facts->>'finish_reason'), ''), 40),
    case when (p_facts->>'cached_tokens') ~ '^[0-9]{1,9}$'
         then least((p_facts->>'cached_tokens')::int, greatest(p_prompt, 0)) else 0 end,
    case when (p_facts->>'cache_write_tokens') ~ '^[0-9]{1,9}$' then (p_facts->>'cache_write_tokens')::int else 0 end,
    case when (p_facts->>'reasoning_tokens') ~ '^[0-9]{1,9}$'
         then least((p_facts->>'reasoning_tokens')::int, greatest(p_completion, 0)) else 0 end
  );
$$;
REVOKE EXECUTE ON FUNCTION public.record_ai_usage_work(p_workspace uuid, p_kind text, p_module text, p_model text, p_prompt integer, p_completion integer, p_cost numeric, p_estimated boolean, p_facts jsonb) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.record_ai_usage_work(p_workspace uuid, p_kind text, p_module text, p_model text, p_prompt integer, p_completion integer, p_cost numeric, p_estimated boolean, p_facts jsonb) TO app_be;

-- ---- from 20261112020900_queue-fair-groups.sql ----
-- queue-fair-groups: forward-only; immutable once on origin/main. Expand only: one nullable column on job_slots and one NEW overload of
-- job_start (five arguments); the four-argument job_start is left exactly as it is, so a back end that does not know groups keeps
-- working. APPLY BEFORE the build that calls the five-argument job_start (the knowledge truths and critique jobs call it).
-- (Stamp handed out as 016900; the lane's untracked migrations were renumbered 016xxx -> 020xxx, so it is 020900 to keep the order.)
--
-- Brain walk 3 (2026-11-11, D-R-8): a workspace runs at most QUEUE_WORKSPACE_CONCURRENCY (2) jobs at once, and a waiting job retries
-- its admission every ~3 s in a lottery with every other waiting job of the workspace. While a 10 MB document is read (73 parts, each a
-- chain of truths jobs), a one-page document's first truths job waited 23 min (M1), critique jobs up to 8 min.
--
-- A FAIR GROUP is what a job belongs to for fairness (the knowledge truths jobs: the document, all its parts one group; the critique
-- runs: one group). The five-argument job_start admits a job of a group that has NO job running in the workspace even when the workspace
-- already runs its limit, up to ONE job beyond it; a job of a group that already runs one keeps the plain limit. So a freed slot goes to a
-- document that has nothing running before another part of the document that already has, and a small document starts within one retry
-- however big the document being read. No group is starved: a group whose jobs all ended is "nothing running" again and goes first.
-- The slot row keeps its group (group_key, null for every job admitted by the four-argument function or with no group).

ALTER TABLE public.job_slots ADD COLUMN group_key text;
ALTER TABLE public.job_slots
    ADD CONSTRAINT job_slots_group_key_check CHECK (group_key IS NULL OR (length(group_key) >= 1 AND length(group_key) <= 200));
CREATE INDEX job_slots_ws_group ON public.job_slots USING btree (workspace_id, group_key) WHERE group_key IS NOT NULL;

CREATE FUNCTION public.job_start(p_queue text, p_id uuid, p_ws_limit integer, p_lease_s integer, p_group text)
    RETURNS TABLE(outcome text, attempt integer, state text, run_token uuid)
    LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $$
declare o public.job_outbox; v_ws uuid; v_busy int; v_mine int; v_limit int; v_attempt int; v_until timestamptz; v_token uuid;
begin
  select * into o from public.job_outbox r where r.id = p_id and r.queue = p_queue for update;
  if o.id is null then return query select 'missing'::text, 0, 'missing'::text, null::uuid; return; end if;
  if o.state in ('done', 'failed') then return query select 'terminal'::text, o.attempts, o.state, o.run_token; return; end if;
  if o.state = 'running' and o.run_lease_until > now() then
    return query select 'busy'::text, o.attempts, o.state, o.run_token; return;
  end if;
  v_ws := o.workspace_id;
  v_until := now() + make_interval(secs => greatest(5, p_lease_s));
  if v_ws is not null then
    perform pg_advisory_xact_lock(hashtextextended('nivo.job-ws:' || v_ws::text, 0));
    delete from public.job_slots s where s.workspace_id = v_ws and s.lease_until < now();
    select count(*) into v_busy from public.job_slots s where s.workspace_id = v_ws and s.job_id <> o.id;
    v_limit := greatest(1, p_ws_limit);
    if p_group is not null then
      select count(*) into v_mine from public.job_slots s
        where s.workspace_id = v_ws and s.group_key = p_group and s.job_id <> o.id;
      -- A group with nothing running may take one slot beyond the limit: it never waits behind another group's chain of jobs.
      if v_mine = 0 then v_limit := v_limit + 1; end if;
    end if;
    if v_busy >= v_limit then return query select 'busy'::text, o.attempts, o.state, o.run_token; return; end if;
    insert into public.job_slots as s (queue, job_id, workspace_id, lease_until, group_key)
    values (o.queue, o.id, v_ws, v_until, p_group)
    on conflict on constraint job_slots_pkey do update set lease_until = excluded.lease_until, group_key = excluded.group_key;
  end if;
  update public.job_outbox r set attempts = r.attempts + 1, state = 'running', started_at = now(), run_lease_until = v_until, run_token = gen_random_uuid()
  where r.id = o.id returning r.attempts, r.run_token into v_attempt, v_token;
  return query select 'started'::text, v_attempt, 'running'::text, v_token;
end $$;

REVOKE EXECUTE ON FUNCTION public.job_start(text, uuid, integer, integer, text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.job_start(text, uuid, integer, integer, text) TO app_be;

-- ---- from 20261112021000_provider-triggers.sql ----
-- provider-triggers: forward-only; immutable once on origin/main. Expand only: two new tables, nothing else touched.
-- Level 3 of a provider (owner rule 2026-11-12: a provider has an API for the interface, tools for the AI, and TRIGGERS that run in the
-- background, each with a switch, "có mới làm"). `provider_trigger_switches` holds, per connected account and declared trigger, whether
-- it is on, since when (events the provider dates before it are not handed on), when it last handed an event on, how many, and the ONE
-- agent the owner bound as the decider of its events (a single column: one account trigger never has two deciders). No row = off.
-- `provider_trigger_dead_events` keeps a run a trigger could not start for an agent after its retries, once per wake key; never dropped.
-- Both hold ids, counts and times only: no transfer content, no mail text.

CREATE TABLE public.provider_trigger_switches (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,
    connection_id uuid NOT NULL REFERENCES public.connections(id) ON DELETE CASCADE,
    trigger_name text NOT NULL,
    enabled boolean DEFAULT false NOT NULL,
    enabled_at timestamptz,
    decider_agent_id uuid REFERENCES public.agents(id) ON DELETE SET NULL,
    last_fired_at timestamptz,
    fired_count integer DEFAULT 0 NOT NULL,
    created_at timestamptz DEFAULT now() NOT NULL,
    updated_at timestamptz DEFAULT now() NOT NULL,
    CONSTRAINT provider_trigger_switches_name_check CHECK ((char_length(trigger_name) BETWEEN 1 AND 100)),
    CONSTRAINT provider_trigger_switches_fired_check CHECK ((fired_count >= 0)),
    CONSTRAINT provider_trigger_switches_account_unique UNIQUE (connection_id, trigger_name)
);

-- The switches of one account of a workspace (the Config tab of the provider page).
CREATE INDEX provider_trigger_switches_workspace ON public.provider_trigger_switches USING btree (workspace_id, connection_id);

CREATE TRIGGER provider_trigger_switches_set_updated_at BEFORE UPDATE ON public.provider_trigger_switches FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

ALTER TABLE public.provider_trigger_switches ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.provider_trigger_switches FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE ON TABLE public.provider_trigger_switches TO app_be;
CREATE POLICY provider_trigger_switches_app_be_select ON public.provider_trigger_switches FOR SELECT TO app_be USING ((workspace_id IS NOT NULL));
CREATE POLICY provider_trigger_switches_app_be_insert ON public.provider_trigger_switches FOR INSERT TO app_be WITH CHECK ((workspace_id IS NOT NULL));
CREATE POLICY provider_trigger_switches_app_be_update ON public.provider_trigger_switches FOR UPDATE TO app_be USING ((workspace_id IS NOT NULL)) WITH CHECK ((workspace_id IS NOT NULL));

CREATE TABLE public.provider_trigger_dead_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,
    connection_id uuid NOT NULL REFERENCES public.connections(id) ON DELETE CASCADE,
    trigger_name text NOT NULL,
    agent_id uuid NOT NULL REFERENCES public.agents(id) ON DELETE CASCADE,
    role text NOT NULL,
    event_key text NOT NULL,
    reason text NOT NULL,
    params jsonb DEFAULT '{}'::jsonb NOT NULL,
    created_at timestamptz DEFAULT now() NOT NULL,
    updated_at timestamptz DEFAULT now() NOT NULL,
    CONSTRAINT provider_trigger_dead_events_name_check CHECK ((char_length(trigger_name) BETWEEN 1 AND 100)),
    CONSTRAINT provider_trigger_dead_events_role_check CHECK ((role = ANY (ARRAY['decider'::text, 'notice'::text]))),
    CONSTRAINT provider_trigger_dead_events_key_check CHECK ((char_length(event_key) BETWEEN 1 AND 1000)),
    CONSTRAINT provider_trigger_dead_events_reason_check CHECK ((char_length(reason) BETWEEN 1 AND 100)),
    CONSTRAINT provider_trigger_dead_events_key_unique UNIQUE (event_key)
);

-- The dead events of one account, newest first (the owner's notice links here).
CREATE INDEX provider_trigger_dead_events_account ON public.provider_trigger_dead_events USING btree (workspace_id, connection_id, created_at DESC);

CREATE TRIGGER provider_trigger_dead_events_set_updated_at BEFORE UPDATE ON public.provider_trigger_dead_events FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

ALTER TABLE public.provider_trigger_dead_events ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.provider_trigger_dead_events FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE ON TABLE public.provider_trigger_dead_events TO app_be;
CREATE POLICY provider_trigger_dead_events_app_be_select ON public.provider_trigger_dead_events FOR SELECT TO app_be USING ((workspace_id IS NOT NULL));
CREATE POLICY provider_trigger_dead_events_app_be_insert ON public.provider_trigger_dead_events FOR INSERT TO app_be WITH CHECK ((workspace_id IS NOT NULL));
CREATE POLICY provider_trigger_dead_events_app_be_update ON public.provider_trigger_dead_events FOR UPDATE TO app_be USING ((workspace_id IS NOT NULL)) WITH CHECK ((workspace_id IS NOT NULL));

-- ---- from 20261112021100_triage-document-nature.sql ----
-- triage-document-nature: forward-only; immutable once on origin/main. Expand only: two new nullable jsonb columns with shape checks on
-- brain_extractions; no backfill, no index (every read is one reading row by primary key, or the documents page's page of rows by
-- primary key). APPLY BEFORE the build (the entity selects the new columns). An older back end never reads them.
--
-- TRIAGE-2 (2026-11-12, D-S-3 / D-S-4): before any passage is triaged, the strong model judges ONCE what the document IS, on its map
-- (outline, samples, the header and sample rows of each table): the shop's own standing rules, a record table or export, a log (chat,
-- diary, minutes, letters), reference material about the trade the shop did not write as its rules, or a mixed document (then by
-- section). Passages inherit the judgement: only rule material is triaged passage by passage and read into truths; records, logs and
-- reference are stored and searchable and file no truth. The judgement is shown on the document and the founder may answer otherwise.
-- 1. brain_extractions.document_nature   the model's reading of one version of the text: {version, contentHash, nature, reason,
--                                         sections[], tables{headerKey: nature}, by}. `reason` is one line in the document's language
--                                         (it may name what the document is about: tenant data, deleted with the document by the FK
--                                         cascade from knowledge_sources, never logged). Another text or map version is read again.
-- 2. brain_extractions.nature_override   the founder's answer {nature, by, at} (nature one of rules, records, log, reference), over the
--                                         model's reading; NULL = none. Saving it opens the reading again at triage (the back end).

ALTER TABLE public.brain_extractions ADD COLUMN document_nature jsonb;
ALTER TABLE public.brain_extractions ADD COLUMN nature_override jsonb;
ALTER TABLE public.brain_extractions
    ADD CONSTRAINT brain_extractions_document_nature_check CHECK (document_nature IS NULL OR jsonb_typeof(document_nature) = 'object');
ALTER TABLE public.brain_extractions
    ADD CONSTRAINT brain_extractions_nature_override_check CHECK (
        nature_override IS NULL
        OR (jsonb_typeof(nature_override) = 'object' AND nature_override ->> 'nature' IN ('rules', 'records', 'log', 'reference'))
    );
COMMENT ON COLUMN public.brain_extractions.document_nature IS 'What the document is, read once per text by the model (TRIAGE-2): nature, one line of reason, sections, tables. Tenant data, never logged.';
COMMENT ON COLUMN public.brain_extractions.nature_override IS 'The founder''s answer on what the document is (rules, records, log, reference), over the model''s reading; NULL = none.';

-- ---- from 20261112021200_mcp-call-log-origin-node.sql ----
-- mcp-call-log-origin-node: forward-only; immutable once on origin/main. Expand only: four nullable columns and one partial index on
-- public.mcp_call_log, nothing else.
-- Rights at node level, phase P1 (owner 2026-11-12: an agent is attached to accounts, each workflow NODE holds the operations it may
-- call). Before any right moves, the audit line of every MCP gateway call (`McpGatewayService.audit`) names where the call came from:
--   origin_kind          the road, as the caller stated it: `node` (a workflow step through the node tool door), or a road OUTSIDE every
--                        node: `mcp_endpoint` (an outside client on the agent's MCP endpoint), `work_item` (an approved gateway call
--                        of a work item), `accounting_desk`, `document_reader` (a screen or reader calling as the first agent
--                        granted), `engine_job` (a module's declared job); null for a caller that stated none;
--   node_key             the key of the graph node whose step made the call (`GraphSpecNode.key`), null outside a node;
--   workflow_id          the workflow of that node, null outside a node and for a run of the agent's own graph no workflow took;
--   workflow_version_id  the version the run is pinned to (the agent graph version of a primary workflow, the workflow version of any
--                        other), null outside a node.
-- They decide nothing: no call is allowed or refused differently. The calls outside a node are counted per road with
--   SELECT origin_kind, count(*) FROM mcp_call_log WHERE workspace_id = $1 AND created_at >= $2 GROUP BY origin_kind
-- and the calls of one node are read on mcp_call_log_node (only the lines a node made).
-- All four are text, not uuid: a caller's ids are written as given and an unexpected shape can never fail the audit insert.
-- Data: no row changes; ADD COLUMN with no default rewrites nothing.
-- ORDER: the api, mcp and cli builds that carry this change write the four columns on EVERY gateway call: apply this migration
-- BEFORE starting those builds, or every call's audit insert fails.

ALTER TABLE public.mcp_call_log ADD COLUMN origin_kind text;
ALTER TABLE public.mcp_call_log ADD COLUMN node_key text;
ALTER TABLE public.mcp_call_log ADD COLUMN workflow_id text;
ALTER TABLE public.mcp_call_log ADD COLUMN workflow_version_id text;
CREATE INDEX mcp_call_log_node ON public.mcp_call_log USING btree (workspace_id, workflow_id, node_key, created_at) WHERE (node_key IS NOT NULL);

-- ---- from 20261112021300_node-account-policies.sql ----
-- node-account-policies: forward-only; immutable once on origin/main. Expand only: two new tables, nothing else touched.
-- Rights at node level, phase P2, in SHADOW (owner 2026-11-12: TIER 1 an agent is attached to connected accounts, the kill switch,
-- public.mcp_connector_access; TIER 2 each workflow NODE picks accounts of the agent and, per account, the operations it may call and
-- auto|ask per write). Nothing reads these tables to allow or refuse a call yet: the agent's ticks (mcp_connector_access.abilities)
-- still decide every call.
--
-- public.node_account_policies: the GRANT. One row = one operation (a full tool id) a node of an agent's workflow may call on one
-- connected account, in a mode, with where the row came from (`template`: a template's proposal the owner agreed; `owner`: the owner's
-- own edit; `migration`: derived from the agent's ticks by `cli node-rights backfill`) and who agreed it. Keyed by the node's KEY in
-- its workflow, never by a version, so it survives a new version of the graph. workflow_id has no foreign key: the workflow records
-- are the entity engine's; a row of a removed workflow is inert and goes with its agent or its account.
-- The backfill only inserts (ON CONFLICT DO NOTHING on the unique key): it never changes or removes a row.
--
-- public.node_policy_shadow_tallies: the SHADOW COMPARE. For every decision the agent-level rights make, the gateway works out what
-- the node's rows would decide and counts the pair of decision codes per (workspace, agent, road, workflow, node, tool). Ids, codes
-- and counts only: no argument, no text of a call. tally_key is the sha256 of the counted tuple (the tuple holds nulls, so the key is
-- one text). A call outside a node is counted under its road with shadow_code `outside_node`. One call is counted by
-- public.node_policy_shadow_count (one statement: a new tuple starts at 1, a known one is counted up and keeps the pinned version of
-- its latest call; SECURITY INVOKER, so the table's own grants and policies hold). Read by `cli node-rights shadow-report`:
--   SELECT * FROM node_policy_shadow_tallies WHERE workspace_id = $1 ORDER BY agent_id, origin_kind, workflow_id, node_key, tool
-- Rows grow with the number of distinct tuples, not with the number of calls.

CREATE TABLE public.node_account_policies (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,
    agent_id uuid NOT NULL REFERENCES public.agents(id) ON DELETE CASCADE,
    workflow_id uuid NOT NULL,
    node_key text NOT NULL,
    connection_id uuid NOT NULL REFERENCES public.connections(id) ON DELETE CASCADE,
    operation text NOT NULL,
    mode text NOT NULL,
    origin text NOT NULL,
    from_version_id uuid,
    agreed_by uuid,
    agreed_at timestamptz,
    created_at timestamptz DEFAULT now() NOT NULL,
    updated_at timestamptz DEFAULT now() NOT NULL,
    CONSTRAINT node_account_policies_node_key_check CHECK ((char_length(node_key) BETWEEN 1 AND 200)),
    CONSTRAINT node_account_policies_operation_check CHECK ((char_length(operation) BETWEEN 1 AND 200)),
    CONSTRAINT node_account_policies_mode_check CHECK ((mode = ANY (ARRAY['auto'::text, 'ask'::text]))),
    CONSTRAINT node_account_policies_origin_check CHECK ((origin = ANY (ARRAY['template'::text, 'owner'::text, 'migration'::text]))),
    CONSTRAINT node_account_policies_row_unique UNIQUE (agent_id, workflow_id, node_key, connection_id, operation)
);

-- The rows of one node (the shadow compare of a call) and of one workspace (the backfill, the roll-up of an agent).
CREATE INDEX node_account_policies_node ON public.node_account_policies USING btree (workspace_id, agent_id, workflow_id, node_key);
-- The holders of one account (the roll-up of a provider's rights tab).
CREATE INDEX node_account_policies_connection ON public.node_account_policies USING btree (workspace_id, connection_id);

CREATE TRIGGER node_account_policies_set_updated_at BEFORE UPDATE ON public.node_account_policies FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

ALTER TABLE public.node_account_policies ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.node_account_policies FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.node_account_policies TO app_be;
CREATE POLICY node_account_policies_app_be_all ON public.node_account_policies TO app_be USING ((workspace_id IS NOT NULL)) WITH CHECK ((workspace_id IS NOT NULL));

CREATE TABLE public.node_policy_shadow_tallies (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    tally_key text NOT NULL,
    workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,
    agent_id uuid NOT NULL REFERENCES public.agents(id) ON DELETE CASCADE,
    origin_kind text NOT NULL,
    workflow_id text,
    node_key text,
    tool text NOT NULL,
    real_code text NOT NULL,
    shadow_code text NOT NULL,
    calls bigint DEFAULT 0 NOT NULL,
    last_version_id text,
    created_at timestamptz DEFAULT now() NOT NULL,
    updated_at timestamptz DEFAULT now() NOT NULL,
    CONSTRAINT node_policy_shadow_tallies_key_check CHECK ((char_length(tally_key) = 64)),
    CONSTRAINT node_policy_shadow_tallies_calls_check CHECK ((calls >= 0)),
    CONSTRAINT node_policy_shadow_tallies_key_unique UNIQUE (tally_key)
);

-- The report of one workspace, in its print order.
CREATE INDEX node_policy_shadow_tallies_workspace ON public.node_policy_shadow_tallies USING btree (workspace_id, agent_id, origin_kind, workflow_id, node_key, tool);

ALTER TABLE public.node_policy_shadow_tallies ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.node_policy_shadow_tallies FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE ON TABLE public.node_policy_shadow_tallies TO app_be;
CREATE POLICY node_policy_shadow_tallies_app_be_select ON public.node_policy_shadow_tallies FOR SELECT TO app_be USING ((workspace_id IS NOT NULL));
CREATE POLICY node_policy_shadow_tallies_app_be_insert ON public.node_policy_shadow_tallies FOR INSERT TO app_be WITH CHECK ((workspace_id IS NOT NULL));
CREATE POLICY node_policy_shadow_tallies_app_be_update ON public.node_policy_shadow_tallies FOR UPDATE TO app_be USING ((workspace_id IS NOT NULL)) WITH CHECK ((workspace_id IS NOT NULL));

CREATE FUNCTION public.node_policy_shadow_count(p_key text, p_workspace uuid, p_agent uuid, p_origin text, p_workflow text, p_node text, p_tool text, p_real text, p_shadow text, p_version text) RETURNS void
    LANGUAGE sql
    SET search_path TO 'public'
    AS $$
  insert into public.node_policy_shadow_tallies (
    tally_key, workspace_id, agent_id, origin_kind, workflow_id, node_key, tool, real_code, shadow_code, calls, last_version_id
  )
  values (p_key, p_workspace, p_agent, p_origin, p_workflow, p_node, p_tool, p_real, p_shadow, 1, p_version)
  on conflict (tally_key) do update
    set calls = public.node_policy_shadow_tallies.calls + 1, last_version_id = excluded.last_version_id, updated_at = now();
$$;
REVOKE EXECUTE ON FUNCTION public.node_policy_shadow_count(p_key text, p_workspace uuid, p_agent uuid, p_origin text, p_workflow text, p_node text, p_tool text, p_real text, p_shadow text, p_version text) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.node_policy_shadow_count(p_key text, p_workspace uuid, p_agent uuid, p_origin text, p_workflow text, p_node text, p_tool text, p_real text, p_shadow text, p_version text) TO app_be;

-- ---- from 20261112021400_truth-verdicts.sql ----
-- truth-verdicts: forward-only; immutable once on origin/main. Expand only: one column with a constant default on
-- public.brain_source_critiques, nothing dropped or rewritten. APPLY BEFORE the build that carries the per-truth verification
-- (the entity selects the column). An older back end never reads it.
--
-- Brain walk 4 (2026-11-11, D-S-1): truths nobody had judged went in force, because the critic answered a bounded list of points
-- for a whole document and a truth no point named was taken for clean. Every waiting truth of a document is now judged on its own
-- (one closed verdict per truth: clean, or a question of a closed kind), and only a truth judged clean goes in force by itself.
--   verified_truths   one mark per truth of the document that carries a verdict: '<truth id>:<stamp>:<c|q>'. The stamp is a digest of
--                     the truth as it was judged (key, value, period, scope, line, passage): a truth whose text changed has no
--                     verdict. A waiting truth with no mark of its present stamp is never applied by the settle; it waits and the
--                     critique of the document stays not_done until it is judged.
-- Data: no row changes. Existing rows get the empty array: the waiting truths of documents critiqued before this column have no
-- verdict and wait until the critique of their document is asked for again (the app's retryBrainCritique). Truths already in
-- force are not judged again.

ALTER TABLE public.brain_source_critiques ADD COLUMN verified_truths text[] DEFAULT '{}'::text[] NOT NULL;
COMMENT ON COLUMN public.brain_source_critiques.verified_truths IS 'Verification verdicts of the document''s truths: <truth id>:<stamp>:<c|q>. No mark of the present stamp = no verdict = never applied by itself.';

-- ---- from 20261112021500_node-rights-switch.sql ----
-- node-rights-switch: forward-only; immutable once on origin/main. Expand only: one new table, nothing else touched.
-- Rights at node level, phase P6: the per-workspace switch "node rights decide". A workspace with NO row, or a row with
-- decides = false, is judged exactly as before (the agent's ticks, public.mcp_connector_access.abilities, decide every call). With
-- decides = true, a call made INSIDE a workflow node is decided by the node's rows (public.node_account_policies) under the agent's
-- attachment (tier 1); every road outside a node keeps the agent-level rule until its own change closes it.
-- Written only by `cli node-rights flip --workspace <id> [--off] [--force] [--since <iso>]`: turning it on is refused unless the
-- shadow report of the workspace shows every compared call agreed; --force is recorded here (forced = true). The figures the flip
-- read are kept beside the switch (compared, differed) as its audit. Rollback = the same command with --off: the ticks were never
-- touched. No GraphQL writes this table.

CREATE TABLE public.node_rights_switches (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,
    decides boolean DEFAULT false NOT NULL,
    forced boolean DEFAULT false NOT NULL,
    compared bigint DEFAULT 0 NOT NULL,
    differed bigint DEFAULT 0 NOT NULL,
    created_at timestamptz DEFAULT now() NOT NULL,
    updated_at timestamptz DEFAULT now() NOT NULL,
    CONSTRAINT node_rights_switches_figures_check CHECK ((compared >= 0 AND differed >= 0)),
    CONSTRAINT node_rights_switches_workspace_unique UNIQUE (workspace_id)
);

CREATE TRIGGER node_rights_switches_set_updated_at BEFORE UPDATE ON public.node_rights_switches FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

ALTER TABLE public.node_rights_switches ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.node_rights_switches FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE ON TABLE public.node_rights_switches TO app_be;
CREATE POLICY node_rights_switches_app_be_select ON public.node_rights_switches FOR SELECT TO app_be USING ((workspace_id IS NOT NULL));
CREATE POLICY node_rights_switches_app_be_insert ON public.node_rights_switches FOR INSERT TO app_be WITH CHECK ((workspace_id IS NOT NULL));
CREATE POLICY node_rights_switches_app_be_update ON public.node_rights_switches FOR UPDATE TO app_be USING ((workspace_id IS NOT NULL)) WITH CHECK ((workspace_id IS NOT NULL));

-- ---- from 20261112021600_extraction-lines-unread.sql ----
-- extraction-lines-unread: forward-only; immutable once on origin/main. Expand only: one new column with a constant default and its check
-- on brain_extractions. APPLY BEFORE the build (the entity selects the column). An older back end never reads it.
--
-- TRIAGE-3 (2026-11-12, D-T-5: plain lines of a rules document filed no truth, with no refused line and no skipped window): every line
-- of a rule passage is now ACCOUNTED for by the truth reading (read into a truth, or listed as skipped with a closed reason); a line
-- neither read nor skipped is asked about once more, then counted here and kept in the reading's notes (`answer_notes`, reason
-- `unaccounted`, the line's text: tenant data, deleted with the document, never logged).
-- brain_extractions.lines_unread   lines of rule passages neither read into a truth nor skipped over the reading.

ALTER TABLE public.brain_extractions ADD COLUMN lines_unread integer NOT NULL DEFAULT 0;
ALTER TABLE public.brain_extractions
    ADD CONSTRAINT brain_extractions_lines_unread_check CHECK (lines_unread >= 0);

-- ---- from 20261112021700_work-item-node-origins.sql ----
-- work-item-node-origins: forward-only; immutable once on origin/main. Expand only: one new table, nothing else touched.
-- Rights at node level, phase P6, holes H6 (work actions) and H2 (approved gateway calls of a work item). A work item a workflow
-- NODE raised (the `work-item.raise` effect) carries where it came from as structured columns: the agent, the run, and the workflow
-- step the host named (workflow, node key, the version the run is pinned to). The engine writes the row when it inserts the item,
-- before the item's gate runs; nothing parses it back out of the item's dedupe key or its fields.
--   - workflow_id NULL with a node key: a run of the agent's own graph that no workflow took (no node row can name it).
--   - node_key NULL: the host named no step on the turn (the origin is known to be a node, which node is not).
-- An item with NO row was raised by no node (the public API, the bookings mailer, the work chain, a command).
-- Read only while the workspace's switch "node rights decide" (public.node_rights_switches) is on: the right of the item's action
-- is then the raising node's. With the switch off nothing reads this table to allow or refuse anything.
-- workflow_id and workflow_version_id have no foreign key: the workflow records are the entity engine's.

CREATE TABLE public.work_item_node_origins (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,
    work_item_id uuid NOT NULL REFERENCES public.work_items(id) ON DELETE CASCADE,
    agent_id uuid NOT NULL REFERENCES public.agents(id) ON DELETE CASCADE,
    run_id text NOT NULL,
    workflow_id uuid,
    node_key text,
    workflow_version_id text,
    created_at timestamptz DEFAULT now() NOT NULL,
    updated_at timestamptz DEFAULT now() NOT NULL,
    CONSTRAINT work_item_node_origins_run_check CHECK ((char_length(run_id) BETWEEN 1 AND 200)),
    CONSTRAINT work_item_node_origins_node_key_check CHECK ((node_key IS NULL OR char_length(node_key) BETWEEN 1 AND 200)),
    CONSTRAINT work_item_node_origins_version_check CHECK ((workflow_version_id IS NULL OR char_length(workflow_version_id) BETWEEN 1 AND 200)),
    -- A step names its node and its pinned version together; a workflow is named only with a step.
    CONSTRAINT work_item_node_origins_step_check CHECK (((node_key IS NULL) = (workflow_version_id IS NULL)) AND (workflow_id IS NULL OR node_key IS NOT NULL)),
    CONSTRAINT work_item_node_origins_item_unique UNIQUE (work_item_id)
);

-- The items one run raised (the audit of a run).
CREATE INDEX work_item_node_origins_run ON public.work_item_node_origins USING btree (workspace_id, run_id);

CREATE TRIGGER work_item_node_origins_set_updated_at BEFORE UPDATE ON public.work_item_node_origins FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

ALTER TABLE public.work_item_node_origins ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.work_item_node_origins FROM anon, authenticated;
GRANT SELECT, INSERT ON TABLE public.work_item_node_origins TO app_be;
CREATE POLICY work_item_node_origins_app_be_select ON public.work_item_node_origins FOR SELECT TO app_be USING ((workspace_id IS NOT NULL));
CREATE POLICY work_item_node_origins_app_be_insert ON public.work_item_node_origins FOR INSERT TO app_be WITH CHECK ((workspace_id IS NOT NULL));

-- ---- from 20261112021800_mcp-endpoint-rights.sql ----
-- mcp-endpoint-rights: forward-only; immutable once on origin/main. Expand only: one new table, nothing else touched.
-- Rights at node level, phase P6, hole H1 (owner 2026-11-12, settled question 4): the MCP endpoint served to an outside client
-- holding an agent's bearer is a holder of its own, "Cong MCP", one per agent, with an EXPLICIT list of (connected account,
-- operation, mode). EMPTY by default. While the workspace's switch "node rights decide" (public.node_rights_switches) is ON, the
-- endpoint discovers and calls a provider operation only when this list holds it on every account the call could act on; the agent's
-- attachment (public.mcp_connector_access, tier 1) stays required, and `ask` asks. With the switch OFF nothing reads this table.
-- Not public.node_account_policies: that table is keyed by a workflow (workflow_id uuid NOT NULL) and a node, and its backfill,
-- re-derivation, shadow report and roll-ups all read a row as a workflow node's; the endpoint is no node.
-- Written only by the console (GraphQL setMcpEndpointRight): the owner widens (a new row, ask -> auto), a manager only narrows (a row
-- taken away, auto -> ask); a core write marked money or irreversible, a plugin's `ask` tool or an operation the pinned API document
-- makes ask-only is never stored `auto`. A row taken away is deleted (the list is the live right, the log line is its history).

CREATE TABLE public.mcp_endpoint_rights (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,
    agent_id uuid NOT NULL REFERENCES public.agents(id) ON DELETE CASCADE,
    connection_id uuid NOT NULL REFERENCES public.connections(id) ON DELETE CASCADE,
    operation text NOT NULL,
    mode text NOT NULL,
    agreed_by uuid NOT NULL,
    agreed_at timestamptz NOT NULL,
    created_at timestamptz DEFAULT now() NOT NULL,
    updated_at timestamptz DEFAULT now() NOT NULL,
    CONSTRAINT mcp_endpoint_rights_operation_check CHECK ((char_length(operation) BETWEEN 1 AND 200)),
    CONSTRAINT mcp_endpoint_rights_mode_check CHECK ((mode = ANY (ARRAY['auto'::text, 'ask'::text]))),
    CONSTRAINT mcp_endpoint_rights_row_unique UNIQUE (agent_id, connection_id, operation)
);

-- The list of one agent's endpoint (every surface call while the switch is on; the console's read).
CREATE INDEX mcp_endpoint_rights_agent ON public.mcp_endpoint_rights USING btree (workspace_id, agent_id);
-- The endpoint holders of one account (the roll-up of a provider's rights tab).
CREATE INDEX mcp_endpoint_rights_connection ON public.mcp_endpoint_rights USING btree (workspace_id, connection_id);

CREATE TRIGGER mcp_endpoint_rights_set_updated_at BEFORE UPDATE ON public.mcp_endpoint_rights FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

ALTER TABLE public.mcp_endpoint_rights ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.mcp_endpoint_rights FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.mcp_endpoint_rights TO app_be;
CREATE POLICY mcp_endpoint_rights_app_be_all ON public.mcp_endpoint_rights TO app_be USING ((workspace_id IS NOT NULL)) WITH CHECK ((workspace_id IS NOT NULL));

-- ---- from 20261112021900_mcp-call-log-records.sql ----
-- mcp-call-log-records: forward-only; immutable once on origin/main. Expand only: two nullable columns and two partial indexes on
-- public.mcp_call_log, nothing else.
-- The agent desk (owner 2026-11-12, drawing webcrm-agent-desk): "records read / records changed" counts RECORDS, not calls. The audit line of
-- every MCP gateway call (`McpGatewayService.audit`) now also keeps, for a call that answered `ok`, the records its adapter STATED in its
-- structured answer:
--   records_read     the records a read answered: a page of the provider envelope `{ ok, status, data: { items }, omitted }` counts its
--                    entries plus the ones it omitted, a single record counts 1;
--   records_changed  the records a write changed: a write answered `ok` in the provider envelope counts 1 (one operation, one record).
-- An adapter that states no count (every answer outside the provider envelope: the native nivo.* tools today) leaves both NULL, and the
-- desk draws a dash, never 0. The effect-rights verdict lines (`connector = 'effect-rights'`) are no calls and stay NULL.
-- The desk reads them two ways:
--   per run    SELECT run_id, sum(records_read), sum(records_changed), count(*) ... FROM mcp_call_log
--              WHERE workspace_id = $1 AND run_id = ANY($2) AND outcome = 'ok' AND connector <> 'effect-rights' GROUP BY run_id
--              on mcp_call_log_run (only the lines that name a run);
--   per day    SELECT sum(records_read), sum(records_changed), count(*) ... FROM mcp_call_log
--              WHERE workspace_id = $1 AND agent_id = $2 AND created_at >= $3 AND created_at < $4 AND outcome = 'ok'
--              AND connector <> 'effect-rights' on mcp_call_log_agent_time (only the lines that name an agent).
-- Data: no row changes; ADD COLUMN with no default rewrites nothing. Old lines keep NULL: the desk shows them uncounted.
-- ORDER: the api, mcp and cli builds that carry this change write both columns on EVERY gateway call: apply this migration BEFORE
-- starting those builds, or every call's audit insert fails.

ALTER TABLE public.mcp_call_log ADD COLUMN records_read integer;
ALTER TABLE public.mcp_call_log ADD COLUMN records_changed integer;
CREATE INDEX mcp_call_log_run ON public.mcp_call_log USING btree (workspace_id, run_id) WHERE (run_id IS NOT NULL);
CREATE INDEX mcp_call_log_agent_time ON public.mcp_call_log USING btree (workspace_id, agent_id, created_at) WHERE (agent_id IS NOT NULL);

-- ---- from 20261112022000_knowledge-sources-blocked-credits.sql ----
-- knowledge-sources-blocked-credits: forward-only; immutable once on origin/main. Expand only: one partial index. May be applied before
-- or after the build (the back end's read is correct without it, only slower on a large table). An older back end never uses it.
--
-- BRAIN-OPS (2026-11-12, D-U-4: out of credits a small document failed at indexing and never resumed). A document of any size that
-- meets an empty credit pool is now stored with its passages searchable by words and waits as `blocked_credits`; the upkeep tick
-- (every 5 minutes) reads the documents that wait, ACROSS workspaces, the longest-waiting first, and queues their index job again once
-- their workspace has credits (`KnowledgeSourcesService.blockedForCredits`). The state is rare, so the index stays a few rows.
-- knowledge_sources_blocked_credits   (updated_at) WHERE status = 'blocked_credits'.

CREATE INDEX knowledge_sources_blocked_credits ON public.knowledge_sources USING btree (updated_at)
    WHERE (status = 'blocked_credits'::text);

-- ---- from 20261112022100_customer-links.sql ----
-- customer-links: forward-only; immutable once on origin/main. Expand only: two new tables, nothing else touched.
-- The trusted link from a customer NIVO holds (a lead of the entity engine) to the customer an OUTSIDE system knows them as, on one
-- connected API account: "this lead is customer <external id> on account <connection>". A run that serves a customer reads the data
-- of an outside system only for the customer its conversation's lead is linked to; with no row it reads none (fail closed).
-- Written by two roads only, both a person's decision: an owner or a manager on the customer's page, and a workflow step's call a
-- person approved on its card. No tool a customer-facing step holds writes it, and nothing infers it from a name or a phone.
--   - one row per (lead, account): a relink replaces the value; an unlink deletes the row. The history is public.customer_link_events.
--   - lead_id has no foreign key: the lead records are the entity engine's.
--   - external_id is the outside system's own identity of the customer (a code, an id): opaque text, never parsed.
-- public.customer_link_events is the audit: append-only, one row per link, relink and unlink, with who decided (`decided_by`: the member's id; for a
-- step's call the approver the approval names, with the agent and the step key it ran under). connection_id has no foreign key there: the
-- history outlives a deleted account.

CREATE TABLE public.customer_links (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,
    lead_id uuid NOT NULL,
    connection_id uuid NOT NULL REFERENCES public.connections(id) ON DELETE CASCADE,
    external_id text NOT NULL,
    created_at timestamptz DEFAULT now() NOT NULL,
    updated_at timestamptz DEFAULT now() NOT NULL,
    CONSTRAINT customer_links_external_id_check CHECK ((char_length(external_id) BETWEEN 1 AND 200)),
    -- The read of every customer-facing call (workspace, lead, account) and the list of one lead's links are served by this key.
    CONSTRAINT customer_links_row_unique UNIQUE (workspace_id, lead_id, connection_id)
);

CREATE TRIGGER customer_links_set_updated_at BEFORE UPDATE ON public.customer_links FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

ALTER TABLE public.customer_links ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.customer_links FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.customer_links TO app_be;
CREATE POLICY customer_links_app_be_all ON public.customer_links TO app_be USING ((workspace_id IS NOT NULL)) WITH CHECK ((workspace_id IS NOT NULL));

CREATE TABLE public.customer_link_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,
    lead_id uuid NOT NULL,
    connection_id uuid NOT NULL,
    action text NOT NULL,
    external_id text NOT NULL,
    previous_external_id text,
    actor_kind text NOT NULL,
    decided_by text NOT NULL,
    agent_id uuid,
    step_key text,
    created_at timestamptz DEFAULT now() NOT NULL,
    updated_at timestamptz DEFAULT now() NOT NULL,
    CONSTRAINT customer_link_events_action_check CHECK ((action = ANY (ARRAY['linked'::text, 'unlinked'::text]))),
    CONSTRAINT customer_link_events_actor_kind_check CHECK ((actor_kind = ANY (ARRAY['member'::text, 'step'::text]))),
    CONSTRAINT customer_link_events_external_id_check CHECK ((char_length(external_id) BETWEEN 1 AND 200)),
    CONSTRAINT customer_link_events_previous_check CHECK ((previous_external_id IS NULL OR char_length(previous_external_id) BETWEEN 1 AND 200)),
    CONSTRAINT customer_link_events_decided_by_check CHECK ((char_length(decided_by) BETWEEN 1 AND 200)),
    CONSTRAINT customer_link_events_step_key_check CHECK ((step_key IS NULL OR char_length(step_key) BETWEEN 1 AND 400)),
    -- A step's call names its agent; a person's act names none.
    CONSTRAINT customer_link_events_actor_check CHECK (((actor_kind = 'step'::text) = (agent_id IS NOT NULL)))
);

-- The history of one lead's links, newest first (the customer's page).
CREATE INDEX customer_link_events_lead ON public.customer_link_events USING btree (workspace_id, lead_id, created_at DESC);

CREATE TRIGGER customer_link_events_set_updated_at BEFORE UPDATE ON public.customer_link_events FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

ALTER TABLE public.customer_link_events ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.customer_link_events FROM anon, authenticated;
GRANT SELECT, INSERT ON TABLE public.customer_link_events TO app_be;
CREATE POLICY customer_link_events_app_be_select ON public.customer_link_events FOR SELECT TO app_be USING ((workspace_id IS NOT NULL));
CREATE POLICY customer_link_events_app_be_insert ON public.customer_link_events FOR INSERT TO app_be WITH CHECK ((workspace_id IS NOT NULL));

-- ---- from 20261112022200_brain-fact-flag-period-unclear.sql ----
-- brain-fact-flag-period-unclear: forward-only; immutable once on origin/main. Expand only: the check on public.brain_facts.review_flags
-- allows one more value; no row is changed, nothing is dropped but the narrower check it replaces. BRAIN-LEAD (loosen, 2026-11-12).
-- 'period_unclear' = the document states a period for this value whose dates could not be computed (a relative window in a document
--                    that states no date of its own, a day that is not a real calendar day, an end before its start). Owner's decision
--                    2026-11-12: such a truth is never dropped and never asked; it is filed WITHOUT a period (default validity), goes in
--                    force like any other, and carries this mark so the page can show "date unclear" on it.
-- Apply this BEFORE the new code boots: the truths reading (TRUTHS_VERSION 10) writes the value at filing.

ALTER TABLE public.brain_facts DROP CONSTRAINT brain_facts_review_flags_check;
ALTER TABLE public.brain_facts ADD CONSTRAINT brain_facts_review_flags_check
    CHECK ((review_flags <@ ARRAY['stale'::text, 'same_meaning'::text, 'period_unclear'::text]));

-- ---- from 20261112022300_node-account-position.sql ----
-- node-account-position: forward-only; immutable once on origin/main. Expand only: one column and one index on
-- public.node_account_policies, nothing else. TOOLS-LEAD slice E4 (binding at install, 2026-11-12; owner key accountsModel2026_11_12).
-- position = the place of the row's PROVIDER in its node's ordered list of providers (0 = the first; providers of one node are
--            ALTERNATIVES, tried in this order by the ToolRunner). Written by the install binding (`bindNodeAccounts`) and by every
--            road that writes a node's rows; every reader of a node's rows reads them in (position, connection, operation) order.
--            The agent's own order of providers is NOT stored: it is read from the agent's template at read time.
-- Data: the rows that exist keep 0 (one provider per node today: the order of alternatives was never written before); no row is
-- rewritten beyond the default ADD COLUMN sets. Nothing decides by the column: it orders, it allows and refuses nothing.
-- ORDER: apply BEFORE the api, mcp and cli builds that carry this change boot: they write and order by the column, so every write
-- and every read of a node's rows fails on a database without it.

ALTER TABLE public.node_account_policies ADD COLUMN position smallint DEFAULT 0 NOT NULL;
ALTER TABLE public.node_account_policies ADD CONSTRAINT node_account_policies_position_check CHECK ((position BETWEEN 0 AND 100));

-- The rows of one node in the order its providers are tried (the binding, the runner's account order, the agent page).
CREATE INDEX node_account_policies_node_position ON public.node_account_policies USING btree (workspace_id, agent_id, workflow_id, node_key, position);

-- ---- from 20261112022400_mcp-call-log-executing-provider.sql ----
-- mcp-call-log-executing-provider: forward-only; immutable once on origin/main. Expand only: four nullable columns on public.mcp_call_log,
-- nothing else.
-- The ONE tool runner (TOOLS-LEAD contract C4.5, slice E1) hands each call of a node the connected account it acts on: the owner of its
-- data first (a customer send: the conversation's own connection), else the node's bound accounts in order, falling back to the next one
-- by the tool's class. Every audit line of such a call (the gateway's `McpGatewayService.audit`, and the runner's own line of an effect
-- `context.effect` made) now also keeps:
--   connection_id  the connected account the call acted on;
--   provider       that account's provider key (`sepay`, `google`, `smtp`, ...);
--   attempt        which try of the call this line is, from 1 (a fallback to the next account is try 2, ...);
--   chosen_by      how the account was chosen: `data_owner`, `order` or `fallback`.
-- A call the runner handed no account (a tool of no provider, a read over every bound account, a line written by a build before this one)
-- leaves all four NULL. Nothing reads them to decide anything: they say on the run page and the desk which account a call went to.
-- Data: no row changes; ADD COLUMN with no default rewrites nothing. Old lines keep NULL.
-- ORDER: the api, mcp and cli builds that carry this change write the four columns on EVERY gateway call: apply this migration BEFORE
-- starting those builds, or every call's audit insert fails.

ALTER TABLE public.mcp_call_log ADD COLUMN connection_id text;
ALTER TABLE public.mcp_call_log ADD COLUMN provider text;
ALTER TABLE public.mcp_call_log ADD COLUMN attempt smallint;
ALTER TABLE public.mcp_call_log ADD COLUMN chosen_by text;

-- ---- from 20261112022600_workspaces-nivo-agent-tool-level.sql ----
-- workspaces-nivo-agent-tool-level: forward-only; immutable once on origin/main.
-- The three-level rename of 2026-11-12 (owner key `levels2026_11_12` of concept tool-naming): a node's MCP tools are `nivo.tool.*`.
-- public.workspaces_nivo_agent() (trigger on public.workspaces; latest body = 20261112014200 block 3) gives a NEW workspace's internal
-- agent its door grants from a list of four tool ids; this file redefines it with the same body and only those four ids changed
-- (scripts/tool-rename-20261112.json): nivo.chat.send -> nivo.tool.chat.send, nivo.chat.profile.get -> nivo.tool.chat.profile.get,
-- nivo.ledger.entry.append -> nivo.tool.ledger.entry.append, nivo.ledger.status.get -> nivo.tool.ledger.status.get.
-- Grants already stored for existing workspaces are re-keyed by `cli tools reseed` (the stores' own re-key), never by this file.
-- Each new id passes the CHECK mcp_tool_grants_tool_check (^[a-z][a-z0-9-]{1,30}\.([a-zA-Z][a-zA-Z0-9_.]{1,80}|\*)$).
CREATE OR REPLACE FUNCTION public.workspaces_nivo_agent() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  v_agent uuid;
begin
  insert into public.agents (workspace_id, module, name, handle, role, instructions, status)
  values (new.id, 'nivo', 'Nivo', 'nivo', 'Runs the declared jobs of the modules',
          'Internal. Calls only the door tools the declared jobs of the modules name.', 'paused')
  returning id into v_agent;
  insert into public.mcp_tool_grants (workspace_id, agent_id, tool, mode)
  select new.id, v_agent, tool, 'auto'
  from unnest(array['nivo.tool.chat.send', 'nivo.tool.chat.profile.get', 'nivo.tool.ledger.entry.append', 'nivo.tool.ledger.status.get']) as tool;
  return null;
end;
$$;

-- ---- from 20261112022700_account-data.sql ----
-- account-data: forward-only; immutable once on origin/main. Expand only: one new partitioned table, nothing else touched.
-- Owner 2026-11-12, concept tool-naming `accountDataTypes2026_11_12` (supersedes the six fixed kinds of `accountData2026_11_12`):
-- every provider account (connection) keeps its own provider data, RAW, in ONE generic key/value table. A row is one thing the
-- PROVIDER sent, exactly as it sent it, keyed by the provider's own id: two feeds reporting one bank transfer are two rows; no merging,
-- no derived identity, no business meaning at ingest. It never decides anything; it is queried.
--   type          the declared type, named by its provider (`telegram.update`, `sepay.transaction`, ...): the partition key
--   type_version  the version of the type's fields the value was written with (old rows keep theirs)
--   key           the provider's own id: the declared key members joined by ":", `sha256:<hex>` when longer than 400 characters
--   value         the members exactly as the type declares them (validated by the engine's schema before every write)
--   processed_at  a `wakes` type: when its consumer completed the row (null = pending); null for the other types
-- Each provider DECLARES its types in code (`defineAccountDataType`, one catalog); one partition per declared type, its CHECK per
-- declared member and its expression indexes are GENERATED into later migrations by `cli account-data plan --write` (never DDL at
-- run time) and listed in db/account-data.manifest.json. This file holds the parent only: NO partition and NO default partition (an
-- undeclared type cannot be written: the intake refuses it before the database is asked).
-- Deleting a connection deletes its rows here (the account's provider data goes with the account); `records` is not touched by that.
--
-- Reads served: one account's rows of one type, newest first (pages, stats, the newest row by an indexed member):
-- `account_data_connection_type_time`. One row by the provider's id (the dedupe of every write, the consumer's lock, a cursor's
-- compare-and-set, an interface answer): the unique key. Cursor readers in the order rows entered the store (created_at, id):
-- `account_data_connection_type_entered`. The retention sweep, per partition, oldest first: `account_data_sweep`.
-- Data: none written here. ORDER: apply before the build that carries the typed `be/src/modules/domain/account-data`.

CREATE TABLE public.account_data (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    type text NOT NULL,
    type_version integer NOT NULL,
    provider text NOT NULL,
    connection_id uuid NOT NULL REFERENCES public.connections(id) ON DELETE CASCADE,
    workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,
    key text NOT NULL,
    value jsonb NOT NULL,
    occurred_at timestamptz DEFAULT now() NOT NULL,
    processed_at timestamptz,
    created_at timestamptz DEFAULT now() NOT NULL,
    updated_at timestamptz DEFAULT now() NOT NULL,
    CONSTRAINT account_data_pkey PRIMARY KEY (type, id),
    CONSTRAINT account_data_type_check CHECK ((char_length(type) BETWEEN 3 AND 50)),
    CONSTRAINT account_data_type_version_check CHECK ((type_version >= 1)),
    CONSTRAINT account_data_key_check CHECK ((char_length(key) BETWEEN 1 AND 400)),
    CONSTRAINT account_data_value_check CHECK ((jsonb_typeof(value) = 'object'::text)),
    CONSTRAINT account_data_key_unique UNIQUE (type, connection_id, key)
) PARTITION BY LIST (type);

-- The concept's index: one account's rows of one type, newest first.
CREATE INDEX account_data_connection_type_time ON public.account_data USING btree (connection_id, type, occurred_at DESC);
-- Cursor readers (`after`): one account's rows of one type in the order they entered the store.
CREATE INDEX account_data_connection_type_entered ON public.account_data USING btree (connection_id, type, created_at, id);
-- The retention sweep only: within one partition (one type), oldest first.
CREATE INDEX account_data_sweep ON public.account_data USING btree (occurred_at);

CREATE TRIGGER account_data_set_updated_at BEFORE UPDATE ON public.account_data FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

ALTER TABLE public.account_data ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.account_data FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.account_data TO app_be;
CREATE POLICY account_data_app_be_select ON public.account_data FOR SELECT TO app_be USING ((workspace_id IS NOT NULL));
CREATE POLICY account_data_app_be_insert ON public.account_data FOR INSERT TO app_be WITH CHECK ((workspace_id IS NOT NULL));
CREATE POLICY account_data_app_be_update ON public.account_data FOR UPDATE TO app_be USING ((workspace_id IS NOT NULL)) WITH CHECK ((workspace_id IS NOT NULL));
CREATE POLICY account_data_app_be_delete ON public.account_data FOR DELETE TO app_be USING ((workspace_id IS NOT NULL));

-- ---- from 20261112022800_agent-tasks-data.sql ----
-- agent-tasks-data: forward-only; immutable once on origin/main. Expand only: one nullable column on public.agent_tasks, nothing else.
-- TOOLS-LEAD (care timers carry their facts, 2026-11-12). A care timer (`nivo.tool.lead.care.schedule`) is one task of the Sales agent;
-- its key already names the step, the record and the ITEM the timer is for (the occasion's id: two occasions of one customer are two
-- tasks, arming one again moves its own). What the timer must hand back when it is due and cannot live in a key (the delivery check's
-- `shipWaits`, how many times it already looked for the shipment) is kept here:
--   data  the small flat record the arming node gave (`payload.data`: at most 8 named text / number / yes-no members, bounded by the
--         tool's payload schema), handed back as `trigger.data` on the care tag; NULL when the arm gave none. Every care arm writes it
--         (NULL clears the record of the arm before); the agent's own task proposals never touch it.
-- Nothing in the database decides by the column: the engine stores and hands it back, the node does its own arithmetic.
-- Data: no row changes; ADD COLUMN with no default rewrites nothing. Timers armed before keep NULL (they never carried data).
-- ORDER: apply BEFORE the api, mcp and cli builds that carry this change boot: their entity selects the column on every read of a task,
-- so every task read fails on a database without it.

ALTER TABLE public.agent_tasks ADD COLUMN data jsonb;
ALTER TABLE public.agent_tasks ADD CONSTRAINT agent_tasks_data_check CHECK ((data IS NULL OR (jsonb_typeof(data) = 'object' AND pg_column_size(data) <= 8192)));

-- ---- from 20261112022900_account-data-types.sql ----
-- account-data-types: forward-only; immutable once on origin/main. GENERATED by `npm run account-data:ddl` from the declared account
-- data types (be/src/modules/domain/account-data-catalog, planned by `accountDataPlanOf`); do not edit by hand. Covered by
-- `npm run account-data:check` (the text must equal what the declarations render); NOT covered by the harness db gate.
-- Expand only: one partition of public.account_data per declared type (20261112022700_account-data.sql holds the parent), a CHECK
-- per declared member (added NOT VALID, then validated) and the declared expression indexes. Owner concept tool-naming
-- `accountDataTypes2026_11_12`. No transaction control.
-- Types:
--   casso.delivery
--   casso.transaction
--   imap.mail
--   imap.read-cursor
--   interface.snapshot
--   meta.event
--   meta.message
--   meta.user
--   payos.delivery
--   payos.transaction
--   sepay.delivery
--   sepay.transaction
--   smtp.mail
--   telegram.message
--   telegram.update
--   telegram.user
--   webhook.delivery
--   zalo_oa.event
--   zalo_oa.message
--   zalo_oa.user

-- create_partition public.account_data_casso_delivery: account_data for values in ('casso.delivery')
CREATE TABLE public."account_data_casso_delivery" PARTITION OF public.account_data FOR VALUES IN ('casso.delivery');
-- add_check public.account_data_casso_delivery:constraint:account_data_casso_delivery_delivery_id_chk: added NOT VALID, then validated
ALTER TABLE public."account_data_casso_delivery" ADD CONSTRAINT "account_data_casso_delivery_delivery_id_chk" CHECK ((value->>'deliveryId') IS NOT NULL AND (jsonb_typeof(value->'deliveryId') = 'string' AND char_length((value->>'deliveryId')) <= 400)) NOT VALID;
ALTER TABLE public."account_data_casso_delivery" VALIDATE CONSTRAINT "account_data_casso_delivery_delivery_id_chk";
-- add_check public.account_data_casso_delivery:constraint:account_data_casso_delivery_credits_chk: added NOT VALID, then validated
