-- ---- from 20261112023100_workflow-trigger-picks.sql ----
-- workflow-trigger-picks: forward-only; immutable once on origin/main. Expand only: one new table, nothing else touched.
-- TOOLS-LEAD U1 (owner key triggerOneSource2026_11_12, CORRECTED 2026-11-12: ONE SOURCE PER UNDERLYING STREAM). A graph's trigger
-- lists providers; in the workspace EVERY attached account of a listed provider is a source when the streams differ (three mailboxes =
-- three sources). Two attached accounts that read the SAME stream (SePay and Casso on one bank account; two connections of one
-- mailbox) hide the graph (`needs_pick`, naming the stream) until the founder picks ONE source for that stream; the other keeps
-- writing raw rows (account_data) and wakes nothing. This table keeps those picks, apart from any graph version, so a pick survives a
-- re-publish, a template update and a rollback of the workflow.
-- workflow_id = the agent.workflow record the pick is for (an entity-engine row: no foreign key); verb = the trigger purpose
--               (`nivo.trigger.payment.credit.received`); stream = the stream key the engine derives from the accounts' public facts
--               (`bank-account:VCB:0123456789`, `mailbox:ketoan@shop.vn`; `connection:<id>` for an unknown one), compared by exact
--               equality; connection_id = the account picked (a deleted connection takes its picks with it).
-- Written only by the owner's consent road (`agreeAgentNodeRights`, member `triggerPicks`), which refuses a pick for a stream the
-- accounts do not contest or an account that does not read it; read by readiness, the trigger takers and the router. A pick whose
-- account no longer reads the stream is ignored (the stream is contested again), never applied to another account.
-- Data: none; no row exists before the first pick. Nothing reads the table on a workspace with no contested stream.
-- ORDER: apply BEFORE the api build that carries this change boots: readiness reads the table only for a contested stream; a failed
-- read is logged and picks nothing, so that graph stays hidden (`needs_pick`) until the table answers: the engine never picks.

CREATE TABLE public.workflow_trigger_picks (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,
    agent_id uuid NOT NULL REFERENCES public.agents(id) ON DELETE CASCADE,
    workflow_id uuid NOT NULL,
    verb text NOT NULL,
    stream text NOT NULL,
    connection_id uuid NOT NULL REFERENCES public.connections(id) ON DELETE CASCADE,
    picked_by uuid NOT NULL,
    picked_at timestamptz DEFAULT now() NOT NULL,
    created_at timestamptz DEFAULT now() NOT NULL,
    updated_at timestamptz DEFAULT now() NOT NULL,
    CONSTRAINT workflow_trigger_picks_verb_check CHECK ((char_length(verb) BETWEEN 1 AND 120)),
    CONSTRAINT workflow_trigger_picks_stream_check CHECK ((char_length(stream) BETWEEN 1 AND 300)),
    CONSTRAINT workflow_trigger_picks_stream_unique UNIQUE (workspace_id, workflow_id, verb, stream)
);

-- The picks of one workflow (readiness, the takers and the router read them per workflow of an agent).
CREATE INDEX workflow_trigger_picks_workflow ON public.workflow_trigger_picks USING btree (workspace_id, agent_id, workflow_id);

CREATE TRIGGER workflow_trigger_picks_set_updated_at BEFORE UPDATE ON public.workflow_trigger_picks FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

ALTER TABLE public.workflow_trigger_picks ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.workflow_trigger_picks FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE ON TABLE public.workflow_trigger_picks TO app_be;
CREATE POLICY workflow_trigger_picks_app_be_select ON public.workflow_trigger_picks FOR SELECT TO app_be USING ((workspace_id IS NOT NULL));
CREATE POLICY workflow_trigger_picks_app_be_insert ON public.workflow_trigger_picks FOR INSERT TO app_be WITH CHECK ((workspace_id IS NOT NULL));
CREATE POLICY workflow_trigger_picks_app_be_update ON public.workflow_trigger_picks FOR UPDATE TO app_be USING ((workspace_id IS NOT NULL)) WITH CHECK ((workspace_id IS NOT NULL));

-- ---- from 20261112023200_connections-provider-domain-media.sql ----
-- connections-provider-domain-media: forward-only; immutable once on origin/main. Expand only: one CHECK widened, no row touched.
-- TOOLS-LEAD (providers are equal; tools are generic purposes shared across providers): six provider keys a workspace may now hold
-- a connection of: the domain registrars `inet` and `tino` (`nivo.tool.domain.*`), the speech and dubbing service `elevenlabs`
-- (`nivo.tool.speech.*`, `nivo.tool.dubbing.*`), the video generation service `veo` (`nivo.tool.video.generate`,
-- `.generation.get`), and the MISA systems `misa_amis` and `misa_meinvoice` (connectable keys; no operation is built yet).
-- `media` (NIVO's host, ffmpeg) is NOT admitted: it has no account, so no connection row can name it (like `nivo`).
-- public.connections_provider_check (baseline) lists the provider keys literally; it is replaced by the same list plus the six.
-- Data: none; no existing row changes (every stored key is in the new list). NOT VALID is not needed: the new list is a superset.
-- ORDER: apply BEFORE the build whose connection form or seed writes one of the six keys; a build that writes none runs on either.
ALTER TABLE public.connections DROP CONSTRAINT connections_provider_check;
ALTER TABLE public.connections ADD CONSTRAINT connections_provider_check CHECK ((provider = ANY (ARRAY[
    'telegram'::text, 'sepay'::text, 'zalo_oa'::text, 'payos'::text, 'casso'::text, 'webhook'::text, 'google'::text, 'smtp'::text,
    'openapi'::text, 'database'::text, 'csv_import'::text, 'imap'::text, 'telegram_user'::text, 'google_drive'::text, 'meta'::text,
    'inet'::text, 'tino'::text, 'elevenlabs'::text, 'veo'::text, 'misa_amis'::text, 'misa_meinvoice'::text
])));

-- ---- from 20261112023300_ai-credits-exact.sql ----
-- ai-credits-exact: forward-only; immutable once on origin/main.
-- Owner, 2026-11-13: a credit is a FRACTION internally. Every model call books `cost_usd / credit_usd_value()` exactly and the pool is
-- debited by the exact SUM; nothing is rounded up per call. The UI shows whole numbers only (used rounds half up, what is left floors,
-- a figure under half a credit shows "<1"), which the be and fe do on read.
-- Replaces public.ai_credit_period (the 20261112014000 definition) with the SAME signature, security, search_path and grants (a
-- CREATE OR REPLACE keeps them): only the arithmetic of `cost` / `prev_cost` changes, from `sum(ceil(cost / value))` (each call up to a whole
-- credit) to `round(sum(cost / value), 6)` (numeric, the sum rounded once to 6 decimals). `used` and `carry` were already numeric, so no
-- return type changes; `credits_limit` (the allowance, whole credits) is untouched. ai_quota_status and settle_credit_topups call this function
-- and need no change: they only round the POOL's overage up to whole top-up credits (`ceil(used - limit)`), never a call.
-- Also corrects the note of billing_config.credit_usd_value, which said "ceil(cost_usd / this) per call".
-- Expand only; apply any time (the be reads `used` as numeric text and keeps 6 decimals).

CREATE OR REPLACE FUNCTION public.ai_credit_period(p_workspace uuid, p_period date) RETURNS TABLE(used numeric, base bigint, carry numeric, credits_limit bigint)
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with p as (
    select p_period as d,
           (p_period - interval '1 month')::date as pd,
           (p_period + interval '1 month')::date as nd
  ), u as (
    select
      coalesce(round(sum(e.cost_usd / public.credit_usd_value()) filter (where (e.created_at at time zone 'Asia/Ho_Chi_Minh')::date >= p.d), 6), 0) as cost,
      coalesce(round(sum(e.cost_usd / public.credit_usd_value()) filter (where (e.created_at at time zone 'Asia/Ho_Chi_Minh')::date < p.d), 6), 0) as prev_cost
    from public.ai_usage_events e, p
    where e.workspace_id = p_workspace and e.kind <> 'guide' and e.failure is null
      and (e.created_at at time zone 'Asia/Ho_Chi_Minh')::date >= p.pd
      and (e.created_at at time zone 'Asia/Ho_Chi_Minh')::date < p.nd
  ), k as (
    select coalesce(sum(x.credits), 0) as credits
    from public.credit_pack_purchases x, p
    where x.workspace_id = p_workspace and x.period = p.d
  ), b as (
    select
      p.d, p.pd, w.created_at, o.credits_limit as own_limit, pl.credits_rollover,
      coalesce(
        o.credits_limit,
        case when pl.per_seat
             then coalesce(w.tier_credits, pl.ai_credits_per_month) * greatest(coalesce(w.seat_count, 1), 1)
             else pl.ai_credits_per_month end
      ) as base
    from p
    left join public.workspaces w on w.id = p_workspace
    left join public.plans pl on pl.code = w.plan_code
    left join public.ai_quota_overrides o on o.workspace_id = p_workspace
  ), c as (
    select b.*,
      case
        when b.own_limit is null and coalesce(b.credits_rollover, false) and b.base is not null
             and (b.created_at at time zone 'Asia/Ho_Chi_Minh')::date < b.d
        then greatest(0, least(
          b.base::numeric,
          b.base::numeric * least(1, (b.d - greatest(b.pd, (b.created_at at time zone 'Asia/Ho_Chi_Minh')::date))::numeric / (b.d - b.pd))
            - (select u.prev_cost from u)))
        else 0
      end as carry
    from b
  )
  select u.cost, c.base, c.carry,
         case when c.base is null then null else floor(c.base + c.carry + (select k.credits from k))::bigint end
  from c cross join u;
$$;

UPDATE public.billing_config
   SET note = 'USD of model token cost that one credit is worth (= 1/885). THE definition of a credit: each call books cost_usd / this exactly (a fraction); the pool is debited by the exact sum, never rounded per call.'
 WHERE key = 'credit_usd_value';

-- ---- from 20261112023400_contacts.sql ----
-- contacts: forward-only; immutable once on origin/main. Expand only: five new tables, nothing else touched.
-- The engine's own SUBJECT of a thread: a contact is every person the agents work with, whatever the source, stage or role; ONE person =
-- ONE contact. Functional modules attach their meaning by their own record types pointing at the contact (`sales.lead`, `hiring.candidate`):
-- the engine knows none of them. No custom field lives on a contact; generic tags do.
--   - public.contacts: one row per person. `state` is `active`, `merged` (a tombstone: another contact took it over, public.contact_merges
--     says which) or `erased` (a tombstone: deleted on a person's decision; its identities and memory are gone, the id stays so history
--     rows that name it do not dangle).
--   - public.contact_identities: the ways to reach / recognise the person, each in ONE normalised form (a phone as `84xxxxxxxxx`, a mail
--     lower-cased, a channel's own user id as the channel gives it, an outside system's customer id as it gives it). `verified` says the
--     identity is proven and `verified_by` how: `channel` (the provider vouches for its own user id), `token` (a one-time link token the
--     person presented), `member` (a person decided, on the contacts page or on an approval card). A self-declared phone or mail is a row
--     with verified = false: a PROPOSAL, never a merge. Only a VERIFIED identity is unique in the workspace: two people may claim the same
--     phone, only one may hold it proven. `joined_by` is the reason the identity came to this contact by a merge (null for one the contact
--     was met with): what the page shows as the merge reason.
--   - public.contact_merges: the ONE redirect table: the contact `from_contact_id` was merged into `into_contact_id` for `reason`. Every
--     engine row keyed by the old id (a run, a stop, a hold, a memory entry written before) follows it at read time; no history is rewritten.
--   - public.contact_link_tokens: one-time link tokens (only the hash is kept): the contact it was issued for, its expiry and its use.
--   - public.contact_events: the audit, append-only: links, unlinks, merges, updates, memory forgotten, erasure, with who decided.
-- account (connection) ids carry no foreign key: an identity and its history outlive a deleted account.

CREATE TABLE public.contacts (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,
    display_name text,
    tags text[] DEFAULT '{}'::text[] NOT NULL,
    state text DEFAULT 'active'::text NOT NULL,
    erased_at timestamptz,
    created_at timestamptz DEFAULT now() NOT NULL,
    updated_at timestamptz DEFAULT now() NOT NULL,
    CONSTRAINT contacts_display_name_check CHECK ((display_name IS NULL OR char_length(display_name) BETWEEN 1 AND 200)),
    CONSTRAINT contacts_tags_check CHECK ((cardinality(tags) <= 20)),
    CONSTRAINT contacts_state_check CHECK ((state = ANY (ARRAY['active'::text, 'merged'::text, 'erased'::text]))),
    CONSTRAINT contacts_erased_check CHECK (((state = 'erased'::text) = (erased_at IS NOT NULL)))
);

-- The contacts page: the people of a workspace, newest first; the name prefix search of people.
CREATE INDEX contacts_recent ON public.contacts USING btree (workspace_id, state, created_at DESC, id DESC);
CREATE INDEX contacts_name ON public.contacts USING btree (workspace_id, lower(display_name) text_pattern_ops) WHERE (state = 'active'::text);

CREATE TRIGGER contacts_set_updated_at BEFORE UPDATE ON public.contacts FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

ALTER TABLE public.contacts ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.contacts FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE ON TABLE public.contacts TO app_be;
CREATE POLICY contacts_app_be_all ON public.contacts TO app_be USING ((workspace_id IS NOT NULL)) WITH CHECK ((workspace_id IS NOT NULL));

CREATE TABLE public.contact_identities (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,
    contact_id uuid NOT NULL REFERENCES public.contacts(id) ON DELETE CASCADE,
    kind text NOT NULL,
    provider text DEFAULT ''::text NOT NULL,
    account text DEFAULT ''::text NOT NULL,
    value text NOT NULL,
    verified boolean NOT NULL,
    verified_by text,
    source text NOT NULL,
    joined_by text,
    created_at timestamptz DEFAULT now() NOT NULL,
    updated_at timestamptz DEFAULT now() NOT NULL,
    CONSTRAINT contact_identities_kind_check CHECK ((kind = ANY (ARRAY['phone'::text, 'email'::text, 'channel'::text, 'external'::text]))),
    CONSTRAINT contact_identities_value_check CHECK ((char_length(value) BETWEEN 1 AND 320)),
    CONSTRAINT contact_identities_provider_check CHECK ((char_length(provider) <= 60)),
    CONSTRAINT contact_identities_account_check CHECK ((char_length(account) <= 100)),
    -- A channel id names its channel and account; an outside customer names its account; a phone or a mail names neither.
    CONSTRAINT contact_identities_scope_check CHECK ((
        (kind = 'channel'::text AND provider <> ''::text AND account <> ''::text)
        OR (kind = 'external'::text AND account <> ''::text)
        OR (kind = ANY (ARRAY['phone'::text, 'email'::text]) AND provider = ''::text AND account = ''::text)
    )),
    CONSTRAINT contact_identities_verified_by_check CHECK ((verified_by IS NULL OR verified_by = ANY (ARRAY['channel'::text, 'token'::text, 'member'::text]))),
    CONSTRAINT contact_identities_verified_check CHECK ((verified = (verified_by IS NOT NULL))),
    CONSTRAINT contact_identities_source_check CHECK ((source = ANY (ARRAY['channel'::text, 'step'::text, 'member'::text, 'form'::text]))),
    CONSTRAINT contact_identities_joined_by_check CHECK ((joined_by IS NULL OR joined_by = ANY (ARRAY['phone_verified'::text, 'email_verified'::text, 'link_token'::text, 'member_approved'::text])))
);

-- One person holds a PROVEN identity: two contacts of a workspace never hold the same verified identity. Claims (verified = false) repeat.
CREATE UNIQUE INDEX contact_identities_verified_unique ON public.contact_identities USING btree (workspace_id, kind, provider, account, value) WHERE verified;
-- The exact lookup of an identifier (resolve, search) and the identities of one contact (the page, a merge).
CREATE INDEX contact_identities_value ON public.contact_identities USING btree (workspace_id, kind, value);
CREATE INDEX contact_identities_contact ON public.contact_identities USING btree (workspace_id, contact_id, created_at, id);

CREATE TRIGGER contact_identities_set_updated_at BEFORE UPDATE ON public.contact_identities FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

ALTER TABLE public.contact_identities ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.contact_identities FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.contact_identities TO app_be;
CREATE POLICY contact_identities_app_be_all ON public.contact_identities TO app_be USING ((workspace_id IS NOT NULL)) WITH CHECK ((workspace_id IS NOT NULL));

CREATE TABLE public.contact_merges (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,
    from_contact_id uuid NOT NULL REFERENCES public.contacts(id) ON DELETE CASCADE,
    into_contact_id uuid NOT NULL REFERENCES public.contacts(id) ON DELETE CASCADE,
    reason text NOT NULL,
    decided_by text,
    created_at timestamptz DEFAULT now() NOT NULL,
    updated_at timestamptz DEFAULT now() NOT NULL,
    CONSTRAINT contact_merges_reason_check CHECK ((reason = ANY (ARRAY['phone_verified'::text, 'email_verified'::text, 'link_token'::text, 'member_approved'::text]))),
    CONSTRAINT contact_merges_self_check CHECK ((from_contact_id <> into_contact_id)),
    CONSTRAINT contact_merges_decided_by_check CHECK ((decided_by IS NULL OR char_length(decided_by) BETWEEN 1 AND 200)),
    -- A contact is merged away once: the redirect of an id is one row.
    CONSTRAINT contact_merges_from_unique UNIQUE (from_contact_id)
);

-- The ids merged into a contact (its aliases), read when a hold or a memory entry keyed by an old id is looked for.
CREATE INDEX contact_merges_into ON public.contact_merges USING btree (workspace_id, into_contact_id);

CREATE TRIGGER contact_merges_set_updated_at BEFORE UPDATE ON public.contact_merges FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

ALTER TABLE public.contact_merges ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.contact_merges FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE ON TABLE public.contact_merges TO app_be;
CREATE POLICY contact_merges_app_be_all ON public.contact_merges TO app_be USING ((workspace_id IS NOT NULL)) WITH CHECK ((workspace_id IS NOT NULL));

CREATE TABLE public.contact_link_tokens (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,
    contact_id uuid NOT NULL REFERENCES public.contacts(id) ON DELETE CASCADE,
    token_hash text NOT NULL,
    expires_at timestamptz NOT NULL,
    used_at timestamptz,
    used_by_contact_id uuid,
    created_at timestamptz DEFAULT now() NOT NULL,
    updated_at timestamptz DEFAULT now() NOT NULL,
    CONSTRAINT contact_link_tokens_hash_check CHECK ((char_length(token_hash) = 64)),
    CONSTRAINT contact_link_tokens_used_check CHECK (((used_at IS NULL) = (used_by_contact_id IS NULL))),
    CONSTRAINT contact_link_tokens_hash_unique UNIQUE (token_hash)
);

CREATE TRIGGER contact_link_tokens_set_updated_at BEFORE UPDATE ON public.contact_link_tokens FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

ALTER TABLE public.contact_link_tokens ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.contact_link_tokens FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE ON TABLE public.contact_link_tokens TO app_be;
CREATE POLICY contact_link_tokens_app_be_all ON public.contact_link_tokens TO app_be USING ((workspace_id IS NOT NULL)) WITH CHECK ((workspace_id IS NOT NULL));

CREATE TABLE public.contact_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,
    contact_id uuid NOT NULL,
    action text NOT NULL,
    detail jsonb DEFAULT '{}'::jsonb NOT NULL,
    actor_kind text NOT NULL,
    decided_by text,
    agent_id uuid,
    step_key text,
    created_at timestamptz DEFAULT now() NOT NULL,
    updated_at timestamptz DEFAULT now() NOT NULL,
    CONSTRAINT contact_events_action_check CHECK ((action = ANY (ARRAY['identity_linked'::text, 'identity_unlinked'::text, 'merged'::text, 'updated'::text, 'memory_forgotten'::text, 'erased'::text]))),
    CONSTRAINT contact_events_actor_kind_check CHECK ((actor_kind = ANY (ARRAY['member'::text, 'step'::text, 'channel'::text]))),
    CONSTRAINT contact_events_decided_by_check CHECK ((decided_by IS NULL OR char_length(decided_by) BETWEEN 1 AND 200)),
    CONSTRAINT contact_events_step_key_check CHECK ((step_key IS NULL OR char_length(step_key) BETWEEN 1 AND 400)),
    -- A step's call names its agent; a person's act and a channel's own word name none.
    CONSTRAINT contact_events_actor_check CHECK (((actor_kind = 'step'::text) = (agent_id IS NOT NULL)))
);

-- The history of one contact, newest first (the page). contact_id has no foreign key: the audit outlives the erasure it records.
CREATE INDEX contact_events_contact ON public.contact_events USING btree (workspace_id, contact_id, created_at DESC);

CREATE TRIGGER contact_events_set_updated_at BEFORE UPDATE ON public.contact_events FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

