CREATE POLICY contact_events_app_be_insert ON public.contact_events FOR INSERT TO app_be WITH CHECK ((workspace_id IS NOT NULL));

-- ---- from 20261113090000_connections-provider-tiktok.sql ----
-- connections-provider-tiktok: forward-only; immutable once on origin/main. Expand only: one CHECK widened, no row touched.
-- TOOLS-LEAD (providers are equal; tools are generic purposes shared across providers): one provider key a workspace may now hold a
-- connection of: the short-video destination `tiktok` (`nivo.tool.tiktok.video.publish`, `.video.status.get`, `.creator.info.get`).
-- public.connections_provider_check lists the provider keys literally; it is replaced by the same list plus `tiktok`.
-- Data: none; no existing row changes (every stored key is in the new list). NOT VALID is not needed: the new list is a superset.
-- ORDER: apply BEFORE the build whose connection form or seed writes the key `tiktok`; a build that writes none runs on either.
ALTER TABLE public.connections DROP CONSTRAINT connections_provider_check;
ALTER TABLE public.connections ADD CONSTRAINT connections_provider_check CHECK ((provider = ANY (ARRAY[
    'telegram'::text, 'sepay'::text, 'zalo_oa'::text, 'payos'::text, 'casso'::text, 'webhook'::text, 'google'::text, 'smtp'::text,
    'openapi'::text, 'database'::text, 'csv_import'::text, 'imap'::text, 'telegram_user'::text, 'google_drive'::text, 'meta'::text,
    'inet'::text, 'tino'::text, 'elevenlabs'::text, 'veo'::text, 'misa_amis'::text, 'misa_meinvoice'::text, 'tiktok'::text
])));

-- ---- from 20261113090100_engine-core-tables.sql ----
-- engine-core-tables: forward-only; immutable once on origin/main. Expand only: the engine's own bookkeeping leaves the records store.
-- Records (public.records) are the mini-database of AGENTS; what the engine keeps to run them is core data with its own tables, each owned
-- by the engine module that writes it. Nothing is copied over: the rows of the old `agent.*` record partitions are not migrated (the dev
-- database is rebuilt from the squashed baseline; runs, checkpoints, stops and ledgers start empty).
-- Every table: the workspace with ON DELETE CASCADE, row-level security for app_be (the back end binds the workspace in code, as the
-- contacts do), the shared updated_at trigger.

-- public.contact_memory: what the workflows remember of a person, core contact data (owned by the contacts module, written by the
-- engine's memory service). One entry per (subject, workflow namespace, node key): the latest outcome of a node, the trigger of a
-- workflow's latest run, or the facts the nodes proved (namespace `$lead`, node `$facts`). The subject is the contact (`contact:<id>`),
-- else the conversation of a person no contact holds yet (`conversation:<id>`). A contact's delete takes its entries; an erasure removes
-- them in code first. `version` fences the facts merge. `agent_id` is attribution (who wrote it), never scope.
CREATE TABLE public.contact_memory (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,
    entry_key text NOT NULL,
    subject_key text NOT NULL,
    contact_id uuid REFERENCES public.contacts(id) ON DELETE CASCADE,
    conversation_id uuid,
    namespace text NOT NULL,
    node_key text NOT NULL,
    step text,
    kind text NOT NULL,
    agent_id uuid REFERENCES public.agents(id) ON DELETE SET NULL,
    workflow_id uuid,
    run_id uuid,
    version_id uuid,
    output jsonb NOT NULL,
    error jsonb,
    written_at timestamptz NOT NULL,
    closed_at timestamptz,
    expires_at timestamptz NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    created_at timestamptz DEFAULT now() NOT NULL,
    updated_at timestamptz DEFAULT now() NOT NULL,
    CONSTRAINT contact_memory_entry_key_check CHECK ((char_length(entry_key) BETWEEN 1 AND 600)),
    CONSTRAINT contact_memory_subject_key_check CHECK ((char_length(subject_key) BETWEEN 1 AND 200)),
    CONSTRAINT contact_memory_kind_check CHECK ((kind = ANY (ARRAY['done'::text, 'failed'::text, 'passed_over'::text, 'trigger'::text, 'facts'::text]))),
    CONSTRAINT contact_memory_output_check CHECK ((jsonb_typeof(output) = 'object'::text)),
    CONSTRAINT contact_memory_version_check CHECK ((version >= 1)),
    CONSTRAINT contact_memory_entry_unique UNIQUE (workspace_id, entry_key)
);

-- A person's entries (a snapshot, a merge, an erasure, a close); one node of one run (resume); the retention sweep; the contact's delete.
CREATE INDEX contact_memory_subject ON public.contact_memory USING btree (workspace_id, subject_key, id);
CREATE INDEX contact_memory_run_node ON public.contact_memory USING btree (workspace_id, run_id, node_key, id) WHERE (run_id IS NOT NULL);
CREATE INDEX contact_memory_expires ON public.contact_memory USING btree (workspace_id, expires_at, id);
CREATE INDEX contact_memory_contact ON public.contact_memory USING btree (contact_id) WHERE (contact_id IS NOT NULL);

CREATE TRIGGER contact_memory_set_updated_at BEFORE UPDATE ON public.contact_memory FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

ALTER TABLE public.contact_memory ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.contact_memory FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.contact_memory TO app_be;
CREATE POLICY contact_memory_app_be_all ON public.contact_memory TO app_be USING ((workspace_id IS NOT NULL)) WITH CHECK ((workspace_id IS NOT NULL));

-- public.run_stops: the stop of one step of one run (owned by the agent threads): ONE row per run and step, reopened by a later stop
-- of the same step (`repeats`); the /chat card is rewritten in place (`card_message_id` names its chat_room_messages line); the lines
-- the stopped step sent customers, the founder's answers and the decision are opaque JSON the stop shapes in code. `contact_id` keeps
-- the id the run named (a merge redirects at read time; no foreign key, a stop outlives the contact's erasure as history).
CREATE TABLE public.run_stops (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,
    run_id uuid NOT NULL,
    step_key text NOT NULL,
    agent_id uuid NOT NULL REFERENCES public.agents(id) ON DELETE CASCADE,
    workflow_id uuid,
    contact_id uuid,
    conversation_id uuid,
    kind text NOT NULL,
    state text DEFAULT 'open'::text NOT NULL,
    reason text NOT NULL,
    question text,
    detail jsonb NOT NULL,
    card_message_id uuid,
    customer_lines jsonb NOT NULL,
    answers jsonb NOT NULL,
    decision jsonb,
    repeats integer DEFAULT 1 NOT NULL,
    stopped_at timestamptz NOT NULL,
    resolved_at timestamptz,
    version integer DEFAULT 1 NOT NULL,
    created_at timestamptz DEFAULT now() NOT NULL,
    updated_at timestamptz DEFAULT now() NOT NULL,
    CONSTRAINT run_stops_step_key_check CHECK ((char_length(step_key) BETWEEN 1 AND 200)),
    CONSTRAINT run_stops_kind_check CHECK ((kind = ANY (ARRAY['ai_report'::text, 'ai_error'::text, 'approval'::text, 'engine'::text]))),
    CONSTRAINT run_stops_state_check CHECK ((state = ANY (ARRAY['open'::text, 'resolved'::text]))),
    CONSTRAINT run_stops_reason_check CHECK ((char_length(reason) <= 20000)),
    CONSTRAINT run_stops_question_check CHECK ((question IS NULL OR char_length(question) <= 20000)),
    CONSTRAINT run_stops_detail_check CHECK ((jsonb_typeof(detail) = 'object'::text)),
    CONSTRAINT run_stops_customer_lines_check CHECK ((jsonb_typeof(customer_lines) = 'object'::text)),
    CONSTRAINT run_stops_answers_check CHECK ((jsonb_typeof(answers) = 'object'::text)),
    CONSTRAINT run_stops_resolved_check CHECK (((state = 'resolved'::text) OR (resolved_at IS NULL))),
    CONSTRAINT run_stops_repeats_check CHECK ((repeats >= 1)),
    CONSTRAINT run_stops_version_check CHECK ((version >= 1)),
    CONSTRAINT run_stops_run_step_unique UNIQUE (workspace_id, run_id, step_key)
);

-- The stops of a run; a person's stops by state (what a customer was told, a freeze); the newest stops of a state (the sweep, /chat).
CREATE INDEX run_stops_run ON public.run_stops USING btree (workspace_id, run_id, created_at, id);
CREATE INDEX run_stops_contact_state ON public.run_stops USING btree (workspace_id, contact_id, state, created_at, id) WHERE (contact_id IS NOT NULL);
CREATE INDEX run_stops_state_stopped ON public.run_stops USING btree (workspace_id, state, stopped_at DESC, id DESC);
CREATE INDEX run_stops_agent ON public.run_stops USING btree (agent_id);

CREATE TRIGGER run_stops_set_updated_at BEFORE UPDATE ON public.run_stops FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

ALTER TABLE public.run_stops ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.run_stops FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.run_stops TO app_be;
CREATE POLICY run_stops_app_be_all ON public.run_stops TO app_be USING ((workspace_id IS NOT NULL)) WITH CHECK ((workspace_id IS NOT NULL));

-- public.contact_freezes: the freeze of one person (owned by the lead freezes): a run of theirs failed for good, so no new run starts
-- for them in any lane until the owner retries or skips. ONE row per person key (`contact:<id>` or `conversation:<id>`, with
-- `|wf:<workflow>` when it holds one workflow), kept across freezes (`episode`); the events held while frozen are `pending` (opaque,
-- replayed in order). `version` fences every write. A contact's delete takes its freeze.
CREATE TABLE public.contact_freezes (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,
    key text NOT NULL,
    contact_id uuid REFERENCES public.contacts(id) ON DELETE CASCADE,
    conversation_id uuid,
    status text DEFAULT 'frozen'::text NOT NULL,
    frozen_run_id uuid,
    agent_id uuid REFERENCES public.agents(id) ON DELETE SET NULL,
    frozen_at timestamptz,
    frozen_reason text,
    step_key text,
    step_title text,
    customer_name text,
    work_item_id uuid,
    episode integer DEFAULT 0 NOT NULL,
    failures integer DEFAULT 0 NOT NULL,
    held_by text,
    released_at timestamptz,
    released_by text,
    release_reason text,
    pending jsonb DEFAULT '{"events": []}'::jsonb NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    created_at timestamptz DEFAULT now() NOT NULL,
    updated_at timestamptz DEFAULT now() NOT NULL,
    CONSTRAINT contact_freezes_key_check CHECK ((char_length(key) BETWEEN 1 AND 200)),
    CONSTRAINT contact_freezes_status_check CHECK ((status = ANY (ARRAY['frozen'::text, 'retrying'::text, 'released'::text]))),
    CONSTRAINT contact_freezes_counts_check CHECK (((episode >= 0) AND (failures >= 0))),
    CONSTRAINT contact_freezes_pending_check CHECK ((jsonb_typeof(pending) = 'object'::text)),
    CONSTRAINT contact_freezes_version_check CHECK ((version >= 1)),
    CONSTRAINT contact_freezes_key_unique UNIQUE (workspace_id, key)
);

-- The people frozen or being retried, oldest first (the sweep, the page); the freeze a run froze (the turn's joined events); a person's.
CREATE INDEX contact_freezes_status_frozen ON public.contact_freezes USING btree (workspace_id, status, frozen_at, id);
CREATE INDEX contact_freezes_run ON public.contact_freezes USING btree (workspace_id, frozen_run_id) WHERE (frozen_run_id IS NOT NULL);
CREATE INDEX contact_freezes_contact ON public.contact_freezes USING btree (workspace_id, contact_id) WHERE (contact_id IS NOT NULL);

CREATE TRIGGER contact_freezes_set_updated_at BEFORE UPDATE ON public.contact_freezes FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

ALTER TABLE public.contact_freezes ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.contact_freezes FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.contact_freezes TO app_be;
CREATE POLICY contact_freezes_app_be_all ON public.contact_freezes TO app_be USING ((workspace_id IS NOT NULL)) WITH CHECK ((workspace_id IS NOT NULL));

-- public.conversation_holds: the agent that keeps a customer conversation between turns (owned by the agent graphs): a workflow that
-- declares `entry.holdsConversation` keeps it while its run has not reached an outcome or handed off. ONE row per conversation,
-- replaced by the next keeper, deleted when the hold ends (no history). The conversation is a chatbot record: no foreign key.
CREATE TABLE public.conversation_holds (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,
    conversation_id uuid NOT NULL,
    agent_id uuid NOT NULL REFERENCES public.agents(id) ON DELETE CASCADE,
    run_id uuid NOT NULL,
    workflow_id uuid,
    held_at timestamptz NOT NULL,
    created_at timestamptz DEFAULT now() NOT NULL,
    updated_at timestamptz DEFAULT now() NOT NULL,
    CONSTRAINT conversation_holds_conversation_unique UNIQUE (workspace_id, conversation_id)
);

CREATE INDEX conversation_holds_agent ON public.conversation_holds USING btree (agent_id);

CREATE TRIGGER conversation_holds_set_updated_at BEFORE UPDATE ON public.conversation_holds FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

ALTER TABLE public.conversation_holds ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON TABLE public.conversation_holds FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.conversation_holds TO app_be;
CREATE POLICY conversation_holds_app_be_all ON public.conversation_holds TO app_be USING ((workspace_id IS NOT NULL)) WITH CHECK ((workspace_id IS NOT NULL));

-- ---- from 20261113090200_mcp-call-log-api-key.sql ----
-- mcp-call-log-api-key: forward-only; immutable once on origin/main. Expand only: two nullable columns, no row touched.
-- TOOLS-LEAD (outbound MCP, `.starciwork/concepts/mcp.md` rule 2 "same audit"): a call through the outbound MCP endpoint runs AS the
-- holder of an API key; its ONE audit line (the same `mcp_call_log` every tool call writes, family `nivo-api` for a NIVO data op)
-- names the key and the holder's account, so the developers page and an audit can say which key and which member made it.
-- Data: none; every existing line keeps NULL in both (they were not made through a key).
-- ORDER: apply BEFORE the build whose mcp app writes `api_key_id` / `actor_user_id`; the api reads neither yet.
ALTER TABLE public.mcp_call_log ADD COLUMN api_key_id uuid REFERENCES public.api_keys(id) ON DELETE SET NULL;
ALTER TABLE public.mcp_call_log ADD COLUMN actor_user_id uuid REFERENCES auth.users(id) ON DELETE SET NULL;

-- ---- from 20261113090300_engine-core-runs-graphs.sql ----
-- engine-core-runs-graphs: forward-only; immutable once on origin/main. Expand only: the rest of the engine's own bookkeeping leaves the
-- records store (after 20261113090100_engine-core-tables: memory, stops, freezes, holds). The graphs of the agents with their versions,
-- sources, proposals and decisions, the workflows with their versions, the runs (with the workflow version each executes: the old
-- `agent.run-workflow` pin is columns of the run), their steps and the effect ledger become core tables, each owned by the engine module
-- that writes it. Nothing is copied over: the rows of the old `agent.*` record partitions are not migrated (the dev database is rebuilt
-- from the squashed baseline; graphs, workflows and runs are seeded again).
-- Every table: the workspace with ON DELETE CASCADE, the agent with ON DELETE CASCADE, row-level security for app_be (the back end binds
-- the workspace in code, as the first four tables do) and for app_engine (these rows are also written inside the entity engine's scoped
-- transaction, whose role is app_engine: the workspace of the scope, `engine_workspace()`), the shared updated_at trigger. `version` is
-- the fence of a table whose writers write under the version they read.

-- public.agent_graphs: the graph of one agent (owned by the agent graphs): the draft the editor changes, the version that decides and
-- whether it decides (`enforced`) or only records (`shadow`). One row per agent.
CREATE TABLE public.agent_graphs (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,
    agent_id uuid NOT NULL REFERENCES public.agents(id) ON DELETE CASCADE,
    installation_id uuid NOT NULL,
    draft jsonb NOT NULL,
    draft_rev integer DEFAULT 1 NOT NULL,
    active_version_id uuid,
    mode text DEFAULT 'enforced'::text NOT NULL,
    mode_set_by uuid,
    mode_set_at timestamptz,
    version integer DEFAULT 1 NOT NULL,
    created_at timestamptz DEFAULT now() NOT NULL,
    updated_at timestamptz DEFAULT now() NOT NULL,
    CONSTRAINT agent_graphs_draft_check CHECK ((jsonb_typeof(draft) = 'object'::text)),
    CONSTRAINT agent_graphs_mode_check CHECK ((mode = ANY (ARRAY['shadow'::text, 'enforced'::text]))),
    CONSTRAINT agent_graphs_version_check CHECK ((version >= 1)),
    CONSTRAINT agent_graphs_agent_unique UNIQUE (workspace_id, agent_id)
);

-- The graph of an installation (the agent an installation runs).
CREATE INDEX agent_graphs_installation ON public.agent_graphs USING btree (workspace_id, installation_id, id);

-- public.agent_graph_versions: one frozen version of the graph of an agent, the program a run is compiled from. Numbered per agent,
-- inserted once, never changed.
CREATE TABLE public.agent_graph_versions (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,
    agent_id uuid NOT NULL REFERENCES public.agents(id) ON DELETE CASCADE,
    number integer NOT NULL,
    document jsonb NOT NULL,
    document_hash text NOT NULL,
    context_version_id uuid,
    change_kind text NOT NULL,
    note text DEFAULT ''::text NOT NULL,
    published_by uuid,
    published_at timestamptz DEFAULT now() NOT NULL,
    created_at timestamptz DEFAULT now() NOT NULL,
    updated_at timestamptz DEFAULT now() NOT NULL,
    CONSTRAINT agent_graph_versions_number_check CHECK ((number >= 1)),
    CONSTRAINT agent_graph_versions_document_check CHECK ((jsonb_typeof(document) = 'object'::text)),
    CONSTRAINT agent_graph_versions_change_kind_check CHECK ((change_kind = ANY (ARRAY['seed'::text, 'chat'::text, 'edit'::text, 'conflict'::text, 'learned'::text, 'template'::text, 'rollback'::text, 'spec'::text, 'copy'::text]))),
    CONSTRAINT agent_graph_versions_number_unique UNIQUE (workspace_id, agent_id, number)
);

-- The versions of an agent, newest first, are served by the unique key (agent, number) read backwards.

-- public.agent_graph_sources: the sources a node or branch of a version cites (a Brain fact, a template, a message), so a changed source
-- is found without opening every version. Deleted with its version.
CREATE TABLE public.agent_graph_sources (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,
    version_id uuid NOT NULL REFERENCES public.agent_graph_versions(id) ON DELETE CASCADE,
    agent_id uuid NOT NULL REFERENCES public.agents(id) ON DELETE CASCADE,
    node_key text NOT NULL,
    branch_key text DEFAULT ''::text NOT NULL,
    kind text NOT NULL,
    ref text NOT NULL,
    value_hash text DEFAULT ''::text NOT NULL,
    created_at timestamptz DEFAULT now() NOT NULL,
    updated_at timestamptz DEFAULT now() NOT NULL,
    CONSTRAINT agent_graph_sources_source_unique UNIQUE (workspace_id, version_id, node_key, branch_key, kind, ref)
);

-- The sources of one kind among some versions.
CREATE INDEX agent_graph_sources_kind_version ON public.agent_graph_sources USING btree (workspace_id, kind, version_id, id);

-- public.agent_graph_proposals: a change the engine proposes to the graph of an agent (a Brain conflict, a learned branch, a template
-- update, a gap, a contract), raised once per agent and cause, decided by a person.
CREATE TABLE public.agent_graph_proposals (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,
    agent_id uuid NOT NULL REFERENCES public.agents(id) ON DELETE CASCADE,
    dedupe_key text NOT NULL,
    kind text NOT NULL,
    status text DEFAULT 'open'::text NOT NULL,
    base_version_id uuid,
    node_key text,
    branch_key text,
    patch jsonb NOT NULL,
    widens boolean DEFAULT false NOT NULL,
    evidence jsonb NOT NULL,
    decided_by uuid,
    decided_at timestamptz,
    result_version_id uuid,
    version integer DEFAULT 1 NOT NULL,
    created_at timestamptz DEFAULT now() NOT NULL,
    updated_at timestamptz DEFAULT now() NOT NULL,
    CONSTRAINT agent_graph_proposals_kind_check CHECK ((kind = ANY (ARRAY['conflict'::text, 'learned'::text, 'template_update'::text, 'gap'::text, 'contract'::text]))),
    CONSTRAINT agent_graph_proposals_status_check CHECK ((status = ANY (ARRAY['open'::text, 'confirmed'::text, 'declined'::text, 'superseded'::text]))),
    CONSTRAINT agent_graph_proposals_patch_check CHECK ((jsonb_typeof(patch) = 'object'::text)),
    CONSTRAINT agent_graph_proposals_evidence_check CHECK ((jsonb_typeof(evidence) = 'object'::text)),
    CONSTRAINT agent_graph_proposals_version_check CHECK ((version >= 1)),
    CONSTRAINT agent_graph_proposals_dedupe_unique UNIQUE (workspace_id, agent_id, dedupe_key)
);

-- The open proposals of an agent, newest first; the proposals of one kind of an agent by status.
CREATE INDEX agent_graph_proposals_agent_status ON public.agent_graph_proposals USING btree (workspace_id, agent_id, status, created_at DESC, id DESC);
CREATE INDEX agent_graph_proposals_agent_kind_status ON public.agent_graph_proposals USING btree (workspace_id, agent_id, kind, status, id);

-- public.agent_graph_decisions: what the graph of an agent decided for one piece of work, recorded once per work item (or per dedupe key
-- when it has none), closed later with how the work ended.
CREATE TABLE public.agent_graph_decisions (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,
    agent_id uuid NOT NULL REFERENCES public.agents(id) ON DELETE CASCADE,
    work_item_id uuid,
    dedupe_key text,
    road text DEFAULT 'work'::text NOT NULL,
    mode text DEFAULT 'shadow'::text NOT NULL,
    gate_verdict text,
    unread jsonb NOT NULL,
    unjudged text,
    subject_type text,
    subject_id text,
    version_id uuid NOT NULL,
    turn_id uuid,
    wake_id uuid,
    action text NOT NULL,
    path jsonb NOT NULL,
    facts jsonb NOT NULL,
    branch_key text NOT NULL,
    outcome text NOT NULL,
    approval_request_id uuid,
    closed_as text,
    shadow_diff boolean DEFAULT false NOT NULL,
    version integer DEFAULT 1 NOT NULL,
    created_at timestamptz DEFAULT now() NOT NULL,
    updated_at timestamptz DEFAULT now() NOT NULL,
    CONSTRAINT agent_graph_decisions_once_check CHECK (((work_item_id IS NOT NULL) OR (dedupe_key IS NOT NULL))),
    CONSTRAINT agent_graph_decisions_road_check CHECK ((road = ANY (ARRAY['work'::text, 'reply'::text, 'tool'::text, 'handover'::text]))),
    CONSTRAINT agent_graph_decisions_mode_check CHECK ((mode = ANY (ARRAY['shadow'::text, 'enforced'::text]))),
    CONSTRAINT agent_graph_decisions_gate_verdict_check CHECK (((gate_verdict IS NULL) OR (gate_verdict = ANY (ARRAY['auto'::text, 'ask'::text])))),
    CONSTRAINT agent_graph_decisions_outcome_check CHECK ((outcome = ANY (ARRAY['auto'::text, 'ask'::text, 'stop'::text, 'divert'::text]))),
    CONSTRAINT agent_graph_decisions_closed_as_check CHECK (((closed_as IS NULL) OR (closed_as = ANY (ARRAY['done'::text, 'approved'::text, 'edited'::text, 'rejected'::text, 'expired'::text, 'stopped'::text])))),
    CONSTRAINT agent_graph_decisions_unread_check CHECK ((jsonb_typeof(unread) = 'object'::text)),
    CONSTRAINT agent_graph_decisions_path_check CHECK ((jsonb_typeof(path) = 'object'::text)),
    CONSTRAINT agent_graph_decisions_facts_check CHECK ((jsonb_typeof(facts) = 'object'::text)),
    CONSTRAINT agent_graph_decisions_version_check CHECK ((version >= 1))
);

-- Once per work item, once per dedupe key; the newest decisions of an agent; the decision of an approval request; the decisions closed
-- after a moment (the learning, newest change first).
CREATE UNIQUE INDEX agent_graph_decisions_work_item_unique ON public.agent_graph_decisions USING btree (workspace_id, work_item_id) WHERE (work_item_id IS NOT NULL);
CREATE UNIQUE INDEX agent_graph_decisions_dedupe_unique ON public.agent_graph_decisions USING btree (workspace_id, dedupe_key) WHERE (dedupe_key IS NOT NULL);
CREATE INDEX agent_graph_decisions_agent_recent ON public.agent_graph_decisions USING btree (workspace_id, agent_id, created_at DESC, id DESC);
CREATE INDEX agent_graph_decisions_request ON public.agent_graph_decisions USING btree (workspace_id, approval_request_id) WHERE (approval_request_id IS NOT NULL);
CREATE INDEX agent_graph_decisions_closed_recent ON public.agent_graph_decisions USING btree (workspace_id, updated_at DESC, id DESC) WHERE (closed_as IS NOT NULL);

-- public.agent_workflows: the workflows of an agent (owned by the agent graphs): a key unique per agent, its place in the list and the
-- version that runs.
CREATE TABLE public.agent_workflows (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,
    agent_id uuid NOT NULL REFERENCES public.agents(id) ON DELETE CASCADE,
    key text NOT NULL,
    name text NOT NULL,
    status text DEFAULT 'draft'::text NOT NULL,
    is_primary boolean DEFAULT false NOT NULL,
    "position" integer DEFAULT 0 NOT NULL,
    active_version_id uuid,
    latest_number integer DEFAULT 0 NOT NULL,
    template_id text,
    template_version integer,
    created_by uuid,
    version integer DEFAULT 1 NOT NULL,
    created_at timestamptz DEFAULT now() NOT NULL,
    updated_at timestamptz DEFAULT now() NOT NULL,
    CONSTRAINT agent_workflows_key_check CHECK ((char_length(key) BETWEEN 1 AND 200)),
    CONSTRAINT agent_workflows_status_check CHECK ((status = ANY (ARRAY['active'::text, 'draft'::text, 'paused'::text]))),
    CONSTRAINT agent_workflows_latest_number_check CHECK ((latest_number >= 0)),
    CONSTRAINT agent_workflows_version_check CHECK ((version >= 1)),
    CONSTRAINT agent_workflows_key_unique UNIQUE (workspace_id, agent_id, key)
);

-- The workflows of an agent in list order, and of every agent agent by agent (an end hand-off).
CREATE INDEX agent_workflows_agent_position ON public.agent_workflows USING btree (workspace_id, agent_id, "position", id);

-- public.agent_workflow_versions: the append-only versions of a workflow, each the full snapshot of its graph, numbered per workflow.
CREATE TABLE public.agent_workflow_versions (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,
    workflow_id uuid NOT NULL REFERENCES public.agent_workflows(id) ON DELETE CASCADE,
    agent_id uuid NOT NULL REFERENCES public.agents(id) ON DELETE CASCADE,
    number integer NOT NULL,
    document jsonb NOT NULL,
    document_hash text NOT NULL,
    change_kind text NOT NULL,
    author_kind text NOT NULL,
    author_id uuid,
    note text DEFAULT ''::text NOT NULL,
    template_id text,
    template_version integer,
    from_number integer,
    graph_version_id uuid,
    published_at timestamptz DEFAULT now() NOT NULL,
    created_at timestamptz DEFAULT now() NOT NULL,
    updated_at timestamptz DEFAULT now() NOT NULL,
    CONSTRAINT agent_workflow_versions_number_check CHECK ((number >= 1)),
    CONSTRAINT agent_workflow_versions_document_check CHECK ((jsonb_typeof(document) = 'object'::text)),
    CONSTRAINT agent_workflow_versions_change_kind_check CHECK ((change_kind = ANY (ARRAY['template'::text, 'blank'::text, 'adopt'::text, 'copy'::text, 'edit'::text, 'proposal'::text, 'accept_template'::text, 'rollback'::text]))),
    CONSTRAINT agent_workflow_versions_author_kind_check CHECK ((author_kind = ANY (ARRAY['owner'::text, 'nivo'::text, 'system'::text]))),
    CONSTRAINT agent_workflow_versions_number_unique UNIQUE (workspace_id, workflow_id, number)
);

-- The version of an agent's workflow that mirrors an agent graph version.
CREATE INDEX agent_workflow_versions_graph_version ON public.agent_workflow_versions USING btree (workspace_id, agent_id, graph_version_id, id) WHERE (graph_version_id IS NOT NULL);

-- public.agent_runs: the durable run of one wake (owned by the agent runs, projected by the agent threads): its status, the trigger intact
-- for a person, the park and resume bookkeeping, and the workflow version it executes (written once, in the transaction that opens the
-- run and marks its thread opened; null for a run of the agent's own graph). One run per wake and planning flag.
CREATE TABLE public.agent_runs (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,
    agent_id uuid NOT NULL REFERENCES public.agents(id) ON DELETE CASCADE,
    wake_id uuid NOT NULL,
    trigger text NOT NULL,
    graph_version_id uuid,
    planning boolean DEFAULT false NOT NULL,
    status text DEFAULT 'running'::text NOT NULL,
    engine text DEFAULT 'langgraph'::text NOT NULL,
    context jsonb NOT NULL,
    error jsonb,
    dead_lettered_at timestamptz,
    parked_build text,
    park_reason text,
    resume_attempts integer DEFAULT 0 NOT NULL,
    resume_not_before timestamptz,
    resumed_at timestamptz,
    resumed_by text,
    resume_reason text,
    wait_work_item_id uuid,
    wait_deadline_at timestamptz,
    step_seq integer DEFAULT 0 NOT NULL,
    started_at timestamptz DEFAULT now() NOT NULL,
    ended_at timestamptz,
    cancelled_at timestamptz,
    cancelled_by text,
    workflow_id uuid REFERENCES public.agent_workflows(id) ON DELETE SET NULL,
    workflow_version_id uuid,
    workflow_version integer,
    version integer DEFAULT 1 NOT NULL,
    created_at timestamptz DEFAULT now() NOT NULL,
    updated_at timestamptz DEFAULT now() NOT NULL,
    CONSTRAINT agent_runs_trigger_check CHECK ((char_length(trigger) <= 120)),
    CONSTRAINT agent_runs_status_check CHECK ((status = ANY (ARRAY['running'::text, 'waiting'::text, 'parked'::text, 'failed'::text, 'done'::text, 'dead'::text, 'compensating'::text, 'compensated'::text, 'cancelled'::text]))),
    CONSTRAINT agent_runs_engine_check CHECK ((engine = ANY (ARRAY['legacy'::text, 'langgraph'::text]))),
    CONSTRAINT agent_runs_context_check CHECK ((jsonb_typeof(context) = 'object'::text)),
    CONSTRAINT agent_runs_error_check CHECK (((error IS NULL) OR (jsonb_typeof(error) = 'object'::text))),
    CONSTRAINT agent_runs_counts_check CHECK (((resume_attempts >= 0) AND (step_seq >= 0))),
    CONSTRAINT agent_runs_pin_check CHECK ((((workflow_id IS NULL) AND (workflow_version_id IS NULL) AND (workflow_version IS NULL)) OR ((workflow_version_id IS NOT NULL) AND (workflow_version IS NOT NULL)))),
    CONSTRAINT agent_runs_version_check CHECK ((version >= 1)),
    CONSTRAINT agent_runs_wake_unique UNIQUE (workspace_id, wake_id, planning)
);

-- The newest runs of an agent (the runs list, the desk, a page of the core read); an agent's runs of a status by end (the waits, the
-- day's counts); the open thread runs by status and resume (the sweep); the runs of a workflow, newest first (the call guard); the
-- runs of a period by start (the dashboard).
CREATE INDEX agent_runs_agent_started ON public.agent_runs USING btree (workspace_id, agent_id, started_at DESC, id DESC);
CREATE INDEX agent_runs_agent_status_ended ON public.agent_runs USING btree (workspace_id, agent_id, status, ended_at DESC, id DESC);
CREATE INDEX agent_runs_status_resume ON public.agent_runs USING btree (workspace_id, status, engine, resume_not_before, id);
CREATE INDEX agent_runs_workflow_started ON public.agent_runs USING btree (workspace_id, agent_id, workflow_id, started_at DESC, id DESC) WHERE (workflow_id IS NOT NULL);
CREATE INDEX agent_runs_started ON public.agent_runs USING btree (workspace_id, started_at, status);

-- public.agent_run_steps: one step of a run as the thread projection writes it (owned by the agent runs): its place, effect, try and the
-- result it stored, unique per run and step key; deleted with its run.
CREATE TABLE public.agent_run_steps (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,
    run_id uuid NOT NULL REFERENCES public.agent_runs(id) ON DELETE CASCADE,
    ordinal integer NOT NULL,
    step_key text NOT NULL,
    node_key text NOT NULL,
    kind text NOT NULL,
    effect jsonb NOT NULL,
    input jsonb NOT NULL,
    result jsonb,
    status text DEFAULT 'pending'::text NOT NULL,
    attempt integer DEFAULT 0 NOT NULL,
    max_attempts integer DEFAULT 3 NOT NULL,
    deadline_ms integer,
    not_before timestamptz,
    wait_item_id uuid,
    work_item_id uuid,
    comp_attempts integer DEFAULT 0 NOT NULL,
    error_code text,
    claimed_until timestamptz,
    started_at timestamptz,
    ended_at timestamptz,
    duration_ms integer,
    door_calls jsonb NOT NULL,
    effect_key text,
    error jsonb,
    version integer DEFAULT 1 NOT NULL,
    created_at timestamptz DEFAULT now() NOT NULL,
    updated_at timestamptz DEFAULT now() NOT NULL,
    CONSTRAINT agent_run_steps_step_key_check CHECK ((char_length(step_key) BETWEEN 1 AND 200)),
    CONSTRAINT agent_run_steps_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'running'::text, 'done'::text, 'failed'::text, 'compensating'::text, 'compensated'::text]))),
    CONSTRAINT agent_run_steps_effect_check CHECK ((jsonb_typeof(effect) = 'object'::text)),
    CONSTRAINT agent_run_steps_input_check CHECK ((jsonb_typeof(input) = 'object'::text)),
    CONSTRAINT agent_run_steps_result_check CHECK (((result IS NULL) OR (jsonb_typeof(result) = 'object'::text))),
    CONSTRAINT agent_run_steps_door_calls_check CHECK ((jsonb_typeof(door_calls) = 'object'::text)),
    CONSTRAINT agent_run_steps_error_check CHECK (((error IS NULL) OR (jsonb_typeof(error) = 'object'::text))),
    CONSTRAINT agent_run_steps_version_check CHECK ((version >= 1)),
    CONSTRAINT agent_run_steps_step_unique UNIQUE (workspace_id, run_id, step_key)
);

-- The steps of a run in order (the projection, the run page, the sweep); the steps about a work item.
CREATE INDEX agent_run_steps_run_ordinal ON public.agent_run_steps USING btree (workspace_id, run_id, ordinal, id);
CREATE INDEX agent_run_steps_work_item ON public.agent_run_steps USING btree (workspace_id, run_id, work_item_id) WHERE (work_item_id IS NOT NULL);
CREATE INDEX agent_run_steps_status ON public.agent_run_steps USING btree (workspace_id, status);

-- public.agent_node_effects: the effect ledger (owned by the graph nodes): ONE row per call key in the workspace, written once after the
-- act by an atomic insert-or-nothing on the unique key (`ON CONFLICT DO NOTHING`), never rewritten: a replay reads the row and answers
-- the kept subject; a race answers the row that won. No run foreign key: a key of another shape names no run, and the ledger outlives
-- the run (business dedupe keys of kept orders and bank transactions).
CREATE TABLE public.agent_node_effects (
    id uuid DEFAULT gen_random_uuid() NOT NULL PRIMARY KEY,
    workspace_id uuid NOT NULL REFERENCES public.workspaces(id) ON DELETE CASCADE,
    effect_key text NOT NULL,
    effect_id text NOT NULL,
    subject_entity text NOT NULL,
    subject_id text NOT NULL,
    undone_at timestamptz,
    run_id uuid,
    step_key text,
    args jsonb,
    facts jsonb,
    created_at timestamptz DEFAULT now() NOT NULL,
    updated_at timestamptz DEFAULT now() NOT NULL,
    CONSTRAINT agent_node_effects_effect_key_check CHECK ((char_length(effect_key) BETWEEN 1 AND 200)),
    CONSTRAINT agent_node_effects_args_check CHECK (((args IS NULL) OR (jsonb_typeof(args) = 'object'::text))),
    CONSTRAINT agent_node_effects_facts_check CHECK (((facts IS NULL) OR (jsonb_typeof(facts) = 'object'::text))),
    CONSTRAINT agent_node_effects_key_unique UNIQUE (workspace_id, effect_key)
);

-- The rows of one run step, oldest first (what a step already did, the lines it told).
CREATE INDEX agent_node_effects_run_step ON public.agent_node_effects USING btree (workspace_id, run_id, step_key, created_at, id) WHERE (run_id IS NOT NULL);

-- The agent foreign keys of the tables above.
CREATE INDEX agent_graph_versions_agent ON public.agent_graph_versions USING btree (agent_id);
CREATE INDEX agent_graph_sources_agent ON public.agent_graph_sources USING btree (agent_id);
CREATE INDEX agent_graph_sources_version ON public.agent_graph_sources USING btree (version_id);
CREATE INDEX agent_graph_proposals_agent ON public.agent_graph_proposals USING btree (agent_id);
CREATE INDEX agent_graph_decisions_agent ON public.agent_graph_decisions USING btree (agent_id);
CREATE INDEX agent_workflow_versions_workflow ON public.agent_workflow_versions USING btree (workflow_id);
CREATE INDEX agent_workflow_versions_agent ON public.agent_workflow_versions USING btree (agent_id);
CREATE INDEX agent_runs_agent ON public.agent_runs USING btree (agent_id);
CREATE INDEX agent_runs_workflow ON public.agent_runs USING btree (workflow_id) WHERE (workflow_id IS NOT NULL);
CREATE INDEX agent_run_steps_run ON public.agent_run_steps USING btree (run_id);

CREATE TRIGGER agent_graphs_set_updated_at BEFORE UPDATE ON public.agent_graphs FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE TRIGGER agent_graph_versions_set_updated_at BEFORE UPDATE ON public.agent_graph_versions FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE TRIGGER agent_graph_sources_set_updated_at BEFORE UPDATE ON public.agent_graph_sources FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE TRIGGER agent_graph_proposals_set_updated_at BEFORE UPDATE ON public.agent_graph_proposals FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE TRIGGER agent_graph_decisions_set_updated_at BEFORE UPDATE ON public.agent_graph_decisions FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE TRIGGER agent_workflows_set_updated_at BEFORE UPDATE ON public.agent_workflows FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE TRIGGER agent_workflow_versions_set_updated_at BEFORE UPDATE ON public.agent_workflow_versions FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE TRIGGER agent_runs_set_updated_at BEFORE UPDATE ON public.agent_runs FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE TRIGGER agent_run_steps_set_updated_at BEFORE UPDATE ON public.agent_run_steps FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE TRIGGER agent_node_effects_set_updated_at BEFORE UPDATE ON public.agent_node_effects FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();

-- Row-level security: app_be binds the workspace in code (as the first four tables); app_engine, inside the entity engine's scope, sees
-- the workspace of the scope only.
ALTER TABLE public.agent_graphs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.agent_graph_versions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.agent_graph_sources ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.agent_graph_proposals ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.agent_graph_decisions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.agent_workflows ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.agent_workflow_versions ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.agent_runs ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.agent_run_steps ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.agent_node_effects ENABLE ROW LEVEL SECURITY;

REVOKE ALL ON TABLE public.agent_graphs, public.agent_graph_versions, public.agent_graph_sources, public.agent_graph_proposals,
    public.agent_graph_decisions, public.agent_workflows, public.agent_workflow_versions, public.agent_runs, public.agent_run_steps,
    public.agent_node_effects FROM anon, authenticated;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.agent_graphs, public.agent_graph_versions, public.agent_graph_sources,
    public.agent_graph_proposals, public.agent_graph_decisions, public.agent_workflows, public.agent_workflow_versions, public.agent_runs,
    public.agent_run_steps, public.agent_node_effects TO app_be, app_engine;

CREATE POLICY agent_graphs_app_be_all ON public.agent_graphs TO app_be USING ((workspace_id IS NOT NULL)) WITH CHECK ((workspace_id IS NOT NULL));
CREATE POLICY agent_graph_versions_app_be_all ON public.agent_graph_versions TO app_be USING ((workspace_id IS NOT NULL)) WITH CHECK ((workspace_id IS NOT NULL));
CREATE POLICY agent_graph_sources_app_be_all ON public.agent_graph_sources TO app_be USING ((workspace_id IS NOT NULL)) WITH CHECK ((workspace_id IS NOT NULL));
CREATE POLICY agent_graph_proposals_app_be_all ON public.agent_graph_proposals TO app_be USING ((workspace_id IS NOT NULL)) WITH CHECK ((workspace_id IS NOT NULL));
CREATE POLICY agent_graph_decisions_app_be_all ON public.agent_graph_decisions TO app_be USING ((workspace_id IS NOT NULL)) WITH CHECK ((workspace_id IS NOT NULL));
CREATE POLICY agent_workflows_app_be_all ON public.agent_workflows TO app_be USING ((workspace_id IS NOT NULL)) WITH CHECK ((workspace_id IS NOT NULL));
CREATE POLICY agent_workflow_versions_app_be_all ON public.agent_workflow_versions TO app_be USING ((workspace_id IS NOT NULL)) WITH CHECK ((workspace_id IS NOT NULL));
CREATE POLICY agent_runs_app_be_all ON public.agent_runs TO app_be USING ((workspace_id IS NOT NULL)) WITH CHECK ((workspace_id IS NOT NULL));
CREATE POLICY agent_run_steps_app_be_all ON public.agent_run_steps TO app_be USING ((workspace_id IS NOT NULL)) WITH CHECK ((workspace_id IS NOT NULL));
CREATE POLICY agent_node_effects_app_be_all ON public.agent_node_effects TO app_be USING ((workspace_id IS NOT NULL)) WITH CHECK ((workspace_id IS NOT NULL));

CREATE POLICY agent_graphs_app_engine_all ON public.agent_graphs TO app_engine USING ((workspace_id = public.engine_workspace())) WITH CHECK ((workspace_id = public.engine_workspace()));
CREATE POLICY agent_graph_versions_app_engine_all ON public.agent_graph_versions TO app_engine USING ((workspace_id = public.engine_workspace())) WITH CHECK ((workspace_id = public.engine_workspace()));
CREATE POLICY agent_graph_sources_app_engine_all ON public.agent_graph_sources TO app_engine USING ((workspace_id = public.engine_workspace())) WITH CHECK ((workspace_id = public.engine_workspace()));
