ALTER TABLE public.workspaces ADD CONSTRAINT workspaces_time_zone_check CHECK (char_length(time_zone) BETWEEN 1 AND 64);
CREATE OR REPLACE FUNCTION public.workspace_storage_bytes(p_workspace uuid) RETURNS bigint LANGUAGE sql STABLE SECURITY DEFINER SET search_path TO 'public', 'storage' AS $function$
  select coalesce(sum(coalesce((o.metadata ->> 'size')::bigint, 0)), 0)::bigint
  from storage.objects o
  where o.bucket_id in ('knowledge-uploads', 'media', 'records')
    and split_part(o.name, '/', 1) = p_workspace::text;
$function$;

